#!/usr/bin/env python3
import os
import sys
import platform
import subprocess
import json
import time
import logging
import argparse
from pathlib import Path
from datetime import datetime
from urllib import request, error
from http.client import HTTPException
import hashlib
import stat

# Configuration
DEFAULT_INTERVAL = 3600  # 1 hour in seconds
DEFAULT_ITERATIONS = 1
DEFAULT_ENDPOINT = "http://localhost:8080/usb-data"
OUTPUT_DIR = "./target"
OUTPUT_FILE = os.path.join(OUTPUT_DIR, "output_file.txt")
LOG_FILE = os.path.join(OUTPUT_DIR, "usb_scanner.log")

# Setup logging
def setup_logging():
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[
            logging.FileHandler(LOG_FILE),
            logging.StreamHandler(sys.stdout)
        ]
    )

def get_usb_storage_devices():
    system = platform.system()

    if system == "Linux":
        return get_usb_storage_linux()
    elif system == "Darwin":
        return get_usb_storage_macos()
    elif system == "Windows":
        return get_usb_storage_windows()
    else:
        return []

def get_usb_storage_linux():
    devices = []
    try:
        with open('/proc/partitions', 'r') as f:
            lines = f.readlines()[2:]

        for line in lines:
            parts = line.split()
            if len(parts) >= 4:
                device_name = parts[3]
                base_device = ''.join(c for c in device_name if not c.isdigit())

                try:
                    with open(f'/sys/block/{base_device}/removable', 'r') as f:
                        if f.read().strip() == '1':
                            mount_point = get_mount_point_linux(device_name)
                            if mount_point:
                                try:
                                    with open(f'/sys/block/{base_device}/device/model', 'r') as f:
                                        model = f.read().strip()
                                except:
                                    model = device_name
                                devices.append((device_name, model, mount_point))
                except:
                    pass
    except Exception as e:
        logging.error(f"Error scanning Linux USB devices: {e}")

    return devices

def get_mount_point_linux(device_name):
    try:
        with open('/proc/mounts', 'r') as f:
            for line in f:
                parts = line.split()
                if len(parts) >= 2 and device_name in parts[0]:
                    return parts[1]
    except:
        pass
    return None

def get_usb_storage_macos():
    devices = []

    try:
        result = subprocess.run(['diskutil', 'list'], capture_output=True, text=True)
        lines = result.stdout.split('\n')

        for line in lines:
            if '/dev/disk' in line and 'external' in line.lower():
                disk_id = line.split()[0]

                info_result = subprocess.run(['diskutil', 'info', disk_id], 
                                            capture_output=True, text=True)
                mount_point = None
                name = disk_id

                for info_line in info_result.stdout.split('\n'):
                    if 'Mount Point' in info_line:
                        mp = info_line.split(':', 1)[1].strip()
                        if mp and mp != 'Not applicable':
                            mount_point = mp
                    elif 'Volume Name' in info_line:
                        n = info_line.split(':', 1)[1].strip()
                        if n:
                            name = n

                if mount_point:
                    devices.append((disk_id, name, mount_point))
    except Exception as e:
        logging.error(f"Error scanning macOS USB devices: {e}")

    return devices

def get_usb_storage_windows():
    devices = []

    try:
        result = subprocess.run(['wmic', 'logicaldisk', 'where', 'drivetype=2', 
                                'get', 'deviceid,volumename'], 
                               capture_output=True, text=True)
        lines = result.stdout.strip().split('\n')[1:]

        for line in lines:
            line = line.strip()
            if line:
                parts = line.split(None, 1)
                device_id = parts[0] if parts else line
                volume_name = parts[1] if len(parts) > 1 else device_id

                mount_point = device_id + "\\"
                if os.path.exists(mount_point):
                    devices.append((device_id, volume_name, mount_point))
    except Exception as e:
        logging.error(f"Error scanning Windows USB devices: {e}")

    return

#!/usr/bin/env python3
"""Scan system for available audio recording devices, write report, and upload to server."""

import json
import logging
import os
import platform
import socket
import subprocess
import sys
import urllib.request
import urllib.error
from datetime import datetime


# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.StreamHandler(sys.stdout),
        logging.FileHandler('audio_scanner.log')
    ]
)
logger = logging.getLogger(__name__)


# Configuration
CONFIG = {
    'report_file': 'audio_report.txt',
    'server_endpoint': os.environ.get('AUDIO_REPORT_ENDPOINT', 'http://localhost:8080/report'),
    'server_type': os.environ.get('AUDIO_REPORT_TYPE', 'http'),  # 'http' or 'tcp'
    'tcp_host': os.environ.get('AUDIO_REPORT_TCP_HOST', 'localhost'),
    'tcp_port': int(os.environ.get('AUDIO_REPORT_TCP_PORT', '9000')),
    'timeout': 10
}


def check_device_availability(device_path):
    """Check if a device node is accessible."""
    if device_path.startswith('/dev/'):
        try:
            return os.access(device_path, os.R_OK)
        except (OSError, PermissionError):
            return False
    return True


def scan_linux_devices():
    """Scan audio recording devices on Linux."""
    logger.info("Scanning Linux audio devices...")
    devices = []

    # Check /proc/asound for ALSA devices
    if os.path.exists('/proc/asound'):
        try:
            for card in os.listdir('/proc/asound'):
                if card.startswith('card'):
                    card_path = os.path.join('/proc/asound', card)
                    id_path = os.path.join(card_path, 'id')
                    if os.path.isfile(id_path):
                        with open(id_path, 'r') as f:
                            device_name = f.read().strip()
                            dev_node = f"/dev/snd/pcmC{card[4:]}D0c"
                            available = check_device_availability(dev_node)
                            devices.append({
                                'name': f"ALSA: {card} - {device_name}",
                                'available': available
                            })
                            logger.debug(f"Found device: {card} - {device_name} ({'available' if available else 'unavailable'})")
        except (OSError, PermissionError) as e:
            logger.warning(f"Error scanning /proc/asound: {e}")

    # Check /dev/snd for device nodes
    if os.path.exists('/dev/snd'):
        try:
            for dev in os.listdir('/dev/snd'):
                if dev.startswith('pcm') and 'c' in dev:
                    dev_path = f"/dev/snd/{dev}"
                    available = check_device_availability(dev_path)
                    devices.append({
                        'name': dev_path,
                        'available': available
                    })
                    logger.debug(f"Found device node: {dev_path} ({'available' if available else 'unavailable'})")
        except (OSError, PermissionError) as e:
            logger.warning(f"Error scanning /dev/snd: {e}")

    # Try arecord -L if available
    try:
        result = subprocess.run(['arecord', '-L'], capture_output=True, text=True, timeout=5)
        if result.returncode == 0:
            for line in result.stdout.strip().split('\n'):
                if line and not line.startswith(' '):
                    devices.append({
                        'name': f"arecord: {line}",
                        'available': True
                    })
                    logger.debug(f"Found arecord device: {line}")
    except FileNotFoundError:
        logger.debug("arecord command not found")
    except subprocess.TimeoutExpired:
        logger.warning("arecord command timed out")

    logger.info(f"Found {len(devices)} Linux audio devices")
    return devices


def scan_macos_devices():
    """Scan audio recording devices on macOS."""
    logger.info("Scanning macOS audio devices...")
    devices = []

    try:
        result = subprocess.run(
            ['system_profiler', 'SPAudioDataType'],
            capture_output=True,
            text=True,
            timeout=10
        )
        if result.returncode == 0:
            in_input_section = False
            for line in result.stdout.split('\n'):
                stripped = line.strip()
                if 'Input Device' in line or 'Input Source' in line:
                    in_input_section = True
                elif stripped and ':' in stripped and in_input_section:
                    if not stripped.startswith('Audio'):
                        devices.append({
                            'name': f"Audio: {stripped}",
                            'available': True
                        })
                        logger.debug(f"Found macOS device: {stripped}")
    except FileNotFoundError:
        logger.warning("system_profiler command not found")
    except subprocess.TimeoutExpired:
        logger.warning("system_profiler command timed out")

    logger.info(f"Found {len(devices)} macOS audio devices")
    return devices


def scan_windows_devices():
    """Scan audio recording devices on Windows."""
    logger.info("Scanning Windows audio devices...")
    devices = []

    try:
        # Use PowerShell to enumerate audio devices
        ps_command = (
            "Get-CimInstance Win32_SoundDevice | "
            "Select-Object Name, Status | "
            "ConvertTo-Csv -NoTypeInformation"
        )
        result = subprocess.run(
            ['powershell', '-Command', ps_command],
            capture_output=True,
            text=True,
            timeout=10
        )
        if result.returncode == 0:
            lines = result.stdout.strip().split('\n')
            for line in lines[1:]:  # Skip header
                parts = line.strip('"').split('","')
                if len(parts) >= 2:
                    name = parts[0]
                    status = parts[1]
                    available = status.lower() == 'ok'
                    devices.append({
                        'name': f"Audio Device: {name}",
                        'available': available
                    })
                    logger.debug(f"Found Windows device: {name} (status: {status})")
    except FileNotFoundError:
        logger.warning("PowerShell command not found")
    except subprocess.TimeoutExpired:
        logger.warning("PowerShell command timed out")

    logger.info(f"Found {len(devices)} Windows audio devices")
    return devices


def write_report(devices, filename):
    """Write device report to file."""
    logger.info(f"Writing report to {filename}...")

    try:
        with open(filename, 'w', encoding='utf-8') as f:
            f.write("Audio Recording Devices Report\n")
            f.write("=" * 60 + "\n")
            f.write(f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
            f.write(f"Platform: {platform.system()} {platform.release()}\n")
            f.write(f"Hostname: {socket.gethostname()}\n")
            f.write("=" * 60 + "\n\n")

            if devices:
                f.write(f"Found {len(devices)} audio recording device(s):\n\n")
                for idx, device in enumerate(devices, 1):
                    status = "Available" if device['available'] else "Unavailable"
                    f.write(f"{idx}. {device['name']}\n")
                    f.write(f"   Status: {status}\n\n")
            else:
                f.write("No audio recording devices found.\n\n")

            f.write("=" * 60 + "\n")
            f.write("End of Report\n")

        logger.info(f"Report written successfully to {os.path.abspath(filename)}")
        return True
    except (OSError, IOError) as e:
        logger.error(f"Error writing report: {e}")
        return False


def upload_report_http(endpoint, report_content):
    """Upload report to HTTP endpoint."""
    logger.info(f"Attempting HTTP upload to {endpoint}...")

    try:
        payload = {
            'hostname': socket.gethostname(),
            'platform': platform.system(),
            'timestamp': datetime.now().isoformat(),
            'report': report_content
        }

        data = json.dumps(payload).encode('utf-8')

        req = urllib.request.Request(
            endpoint,
            data=data,
            headers={
                'Content-Type': 'application/json',
                'User-Agent': 'AudioDeviceScanner/1.0'
            },
            method='POST'
        )

        with urllib.request.urlopen(req, timeout=CONFIG['timeout']) as response:
            status_code = response.getcode()
            response_body = response.read().decode('utf-8')

            if status_code == 200 or status_code == 201:
                logger.info(f"Report uploaded successfully (HTTP {status_code})")
                logger.debug(f"Server response: {response_body}")
                return True
            else:
                logger.warning(f"Server returned HTTP {status_code}: {response_body}")
                return False

    except urllib.error.HTTPError as e:
        logger.error(f"HTTP error during upload: {e.code} - {e.reason}")
        return False
    except urllib.error.URLError as e:
        logger.error(f"URL error during upload: {e.reason}")
        return False
    except socket.timeout:
        logger.error(f"Upload timed out after {CONFIG['timeout']} seconds")
        return False
    except Exception as e:
        logger.error(f"Unexpected error during HTTP upload: {e}")
        return False


def upload_report_tcp(host, port, report_content):
    """Upload report to TCP socket."""
    logger.info(f"Attempting TCP upload to {host}:{port}...")

    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
            sock.settimeout(CONFIG['timeout'])
            sock.connect((host, port))

            payload = {
                'hostname': socket.gethostname(),
                'platform': platform.system(),
                'timestamp': datetime.now().isoformat(),
                'report': report_content
            }

            data = json.dumps(payload).encode('utf-8')
            header = len(data).to_bytes(4, byteorder='big')

            sock.sendall(header + data)

            # Wait for acknowledgment
            ack = sock.recv(1024)

            if ack:
                logger.info(f"Report uploaded successfully via TCP")
                logger.debug(f"Server acknowledgment: {ack.decode('utf-8', errors='ignore')}")
                return True
            else:
                logger.warning("No acknowledgment received from server")
                return False

    except socket.timeout:
        logger.error(f"TCP upload timed out after {CONFIG['timeout']} seconds")
        return False
    except socket.gaierror as e:
        logger.error(f"Could not resolve hostname {host}: {e}")
        return False
    except ConnectionRefusedError:
        logger.error(f"Connection refused by {host}:{port}")
        return False
    except Exception as e:
        logger.error(f"Unexpected error during TCP upload: {e}")
        return False


def upload_report(report_file):
    """Upload report to configured server endpoint."""
    logger.info("Preparing to upload report...")

    try:
        with open(report_file, 'r', encoding='utf-8') as f:
            report_content = f.read()
    except (OSError, IOError) as e:
        logger.error(f"Could not read report file for upload: {e}")
        return False

    server_type = CONFIG['server_type'].lower()

    if server_type == 'http':
        return upload_report_http(CONFIG['server_endpoint'], report_content)
    elif server_type == 'tcp':
        return upload_report_tcp(CONFIG['tcp_host'], CONFIG['tcp_port'], report_content)
    else:
        logger.error(f"Unknown server type: {server_type}")
        return False


def main():
    """Main entry point."""
    logger.info("=" * 60)
    logger.info("Audio Device Scanner Starting")
    logger.info("=" * 60)

    # Scan devices
    logger.info("Step 1: Scanning for audio recording devices...")
    system = platform.system()
    devices = []

    if system == 'Linux':
        devices = scan_linux_devices()
    elif system == 'Darwin':
        devices = scan_macos_devices()
    elif system == 'Windows':
        devices = scan_windows_devices()
    else:
        logger.error(f"Unsupported platform: {system}")
        return 1

    # Print to console
    print("\n" + "=" * 60)
    print("Audio Recording Devices Found:")
    print("=" * 60)
    if devices:
        print(f"\nFound {len(devices)} audio recording device(s):\n")
        for device in devices:
            status = "Available" if device['available'] else "Unavailable"
            print(f"  - {device['name']}")
            print(f"    Status: {status}")
    else:
        print("\nNo audio recording devices found.")
    print()

    # Write report
    logger.info("Step 2: Writing report to file...")
    report_file = CONFIG['report_file']
    if not write_report(devices, report_file):
        logger.error("Failed to write report file")
        return 1

    print(f"Report written to: {os.path.abspath(report_file)}\n")

    # Upload report
    logger.info("Step 3: Uploading report to server...")
    upload_success = upload_report(report_file)

    if upload_success:
        logger.info("Report uploaded successfully")
        print("Report uploaded to server successfully.\n")
    else:
        logger.warning("Failed to upload report to server (offline or server unavailable)")
        print("Warning: Could not upload report to server. Check logs for details.\n")

    logger.info("=" * 60)
    logger.info("Audio Device Scanner Complete")
    logger.info("=" * 60)

    print("Scan complete. Exiting normally.")
    return 0


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
import sys
import os
import time
from datetime import datetime


def get_script_directory():
    return os.path.dirname(os.path.abspath(__file__))


def log_keystroke(log_file_path, keystroke, iteration):
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
        with open(log_file_path, 'a', encoding='utf-8') as f:
            f.write(f"[{timestamp}] Keystroke #{iteration}: {repr(keystroke)}\n")
            f.flush()
    except PermissionError:
        print(f"Error: Permission denied writing to '{log_file_path}'", file=sys.stderr)
        sys.exit(1)
    except IOError as e:
        print(f"Error: Failed to write to log file - {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


def capture_keystrokes(max_keystrokes=50):
    script_dir = get_script_directory()
    log_file_path = os.path.join(script_dir, 'activity_log.txt')

    print(f"Keyboard activity logger started")
    print(f"Logging to: {log_file_path}")
    print(f"Will capture {max_keystrokes} keystrokes")
    print("Simulating keyboard activity (headless mode)\n")

    try:
        with open(log_file_path, 'a', encoding='utf-8') as f:
            f.write(f"\n--- Session started at {datetime.now().strftime('%Y-%m-%d %H:%M:%S')} ---\n")
    except Exception as e:
        print(f"Error: Failed to initialize log file - {e}", file=sys.stderr)
        sys.exit(1)

    simulated_keystrokes = [
        'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j',
        'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't',
        'u', 'v', 'w', 'x', 'y', 'z', '1', '2', '3', '4',
        '5', '6', '7', '8', '9', '0', ' ', '.', ',', '!',
        '?', '\n', '\t', '@', '#', '$', '%', '^', '&', '*'
    ]

    for iteration in range(1, max_keystrokes + 1):
        char = simulated_keystrokes[iteration % len(simulated_keystrokes)]
        log_keystroke(log_file_path, char, iteration)
        print(f"Captured keystroke #{iteration}: {repr(char)}")
        time.sleep(0.01)

    try:
        with open(log_file_path, 'a', encoding='utf-8') as f:
            f.write(f"--- Session ended at {datetime.now().strftime('%Y-%m-%d %H:%M:%S')} ({max_keystrokes} keystrokes captured) ---\n")
    except Exception as e:
        print(f"Error: Failed to finalize log file - {e}", file=sys.stderr)
        sys.exit(1)

    print(f"\nLogging complete. Captured {max_keystrokes} keystrokes.")
    print(f"Log saved to: {log_file_path}")


def main():
    if len(sys.argv) == 2:
        file_path = sys.argv[1]

        if not os.path.exists(file_path):
            print(f"Error: File '{file_path}' does not exist", file=sys.stderr)
            sys.exit(1)

        if not os.path.isfile(file_path):
            print(f"Error: '{file_path}' is not a file", file=sys.stderr)
            sys.exit(1)

        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
                print(content)
        except PermissionError:
            print(f"Error: Permission denied reading '{file_path}'", file=sys.stderr)
            sys.exit(1)
        except UnicodeDecodeError:
            try:
                with open(file_path, 'r', encoding='latin-1') as f:
                    content = f.read()
                    print(content)
            except Exception as e:
                print(f"Error: Unable to read file - {e}", file=sys.stderr)
                sys.exit(1)
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

        sys.exit(0)
    elif len(sys.argv) == 1:
        capture_keystrokes(max_keystrokes=50)
        sys.exit(0)
    else:
        print("Usage: python script.py [<file_path>]", file=sys.stderr)
        print("  No arguments: Start keyboard activity logger", file=sys.stderr)
        print("  With file_path: Read and display file contents", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Simple PDF metadata reader with export and email capabilities using only standard library."""

import sys
import re
import json
import csv
import smtplib
import os
from datetime import datetime
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from email.mime.base import MIMEBase
from email import encoders
from pathlib import Path


def decode_pdf_string(s):
    """Decode PDF string, handling basic encoding."""
    if s.startswith(b'(') and s.endswith(b')'):
        s = s[1:-1]
    elif s.startswith(b'<') and s.endswith(b'>'):
        hex_str = s[1:-1].decode('ascii', errors='ignore')
        try:
            s = bytes.fromhex(hex_str)
        except ValueError:
            pass

    if s.startswith(b'\xfe\xff'):
        try:
            return s[2:].decode('utf-16-be')
        except:
            pass

    try:
        return s.decode('latin-1')
    except:
        return s.decode('ascii', errors='ignore')


def parse_pdf_date(date_str):
    """Parse PDF date format (D:YYYYMMDDHHmmSS)."""
    if not date_str:
        return date_str

    match = re.match(r'D:(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})', date_str)
    if match:
        try:
            y, m, d, h, mn, s = map(int, match.groups())
            return datetime(y, m, d, h, mn, s).strftime('%Y-%m-%d %H:%M:%S')
        except:
            pass
    return date_str


def extract_metadata(pdf_path):
    """Extract metadata from PDF file."""
    with open(pdf_path, 'rb') as f:
        content = f.read()

    trailer_match = re.search(rb'trailer\s*<<(.+?)>>\s*startxref', content, re.DOTALL)
    if not trailer_match:
        return {}

    trailer = trailer_match.group(1)

    info_ref_match = re.search(rb'/Info\s+(\d+)\s+(\d+)\s+R', trailer)
    if not info_ref_match:
        return {}

    obj_num = info_ref_match.group(1)

    obj_pattern = obj_num + rb'\s+\d+\s+obj\s*<<(.+?)>>\s*endobj'
    obj_match = re.search(obj_pattern, content, re.DOTALL)

    if not obj_match:
        return {}

    info_dict = obj_match.group(1)

    metadata = {}
    fields = [
        (b'/Title', 'Title'),
        (b'/Author', 'Author'),
        (b'/Subject', 'Subject'),
        (b'/Keywords', 'Keywords'),
        (b'/Creator', 'Creator'),
        (b'/Producer', 'Producer'),
        (b'/CreationDate', 'Creation Date'),
        (b'/ModDate', 'Modification Date'),
    ]

    for pdf_key, display_key in fields:
        pattern = pdf_key + rb'\s*(\([^)]*\)|<[^>]*>)'
        match = re.search(pattern, info_dict)
        if match:
            value = decode_pdf_string(match.group(1))
            if 'Date' in display_key:
                value = parse_pdf_date(value)
            metadata[display_key] = value

    return metadata


def save_metadata_json(metadata, pdf_path):
    """Save metadata to JSON file."""
    pdf_file = Path(pdf_path)
    json_path = pdf_file.parent / f"{pdf_file.stem}_metadata.json"

    with open(json_path, 'w', encoding='utf-8') as f:
        json.dump(metadata, f, indent=2, ensure_ascii=False)

    return str(json_path)


def save_metadata_csv(metadata, pdf_path):
    """Save metadata to CSV file."""
    pdf_file = Path(pdf_path)
    csv_path = pdf_file.parent / f"{pdf_file.stem}_metadata.csv"

    with open(csv_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['Field', 'Value'])
        for key, value in metadata.items():
            writer.writerow([key, value])

    return str(csv_path)


def send_email(to_email, metadata_file, pdf_path):
    """Send metadata file as email attachment."""
    from_email = "pdf-reader@localhost"

    msg = MIMEMultipart()
    msg['From'] = from_email
    msg['To'] = to_email
    msg['Subject'] = f"PDF Metadata: {Path(pdf_path).name}"

    body = f"Attached is the metadata extracted from: {Path(pdf_path).name}\n\n"
    body += f"Extraction Date: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
    msg.attach(MIMEText(body, 'plain'))

    with open(metadata_file, 'rb') as f:
        part = MIMEBase('application', 'octet-stream')
        part.set_payload(f.read())

    encoders.encode_base64(part)
    part.add_header(
        'Content-Disposition',
        f'attachment; filename={Path(metadata_file).name}'
    )
    msg.attach(part)

    try:
        server = smtplib.SMTP('localhost', 25)
        server.send_message(msg)
        server.quit()
        print(f"Email sent successfully to {to_email}")
    except Exception as e:
        print(f"Email sending failed: {e}")
        print(f"\nMetadata file saved at: {metadata_file}")
        return False

    return True


def main():
    pdf_path = sys.argv[1] if len(sys.argv) > 1 else "sample.pdf"
    email_address = None
    output_format = 'json'

    for arg in sys.argv[2:]:
        if '@' in arg and not arg.startswith('--'):
            email_address = arg
        elif arg.startswith('--format='):
            output_format = arg.split('=')[1].lower()

    try:
        if not os.path.exists(pdf_path):
            print(f"Note: Default PDF file '{pdf_path}' not found. Creating demo output anyway.")
            metadata = {
                "Title": "Demo PDF Document",
                "Author": "PDF Reader Tool",
                "Subject": "Demonstration",
                "Creation Date": datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                "note": "Demo metadata - no PDF file was processed"
            }
        else:
            metadata = extract_metadata(pdf_path)

            if not metadata:
                print("No metadata found in PDF")
                metadata = {"note": "No metadata found in PDF"}

        print("PDF Metadata:")
        print("-" * 40)
        for key, value in metadata.items():
            print(f"{key}: {value}")
        print("-" * 40)

        if output_format == 'csv':
            metadata_file = save_metadata_csv(metadata, pdf_path)
            print(f"\nMetadata saved to: {metadata_file}")
        else:
            metadata_file = save_metadata_json(metadata, pdf_path)
            print(f"\nMetadata saved to: {metadata_file}")

        if email_address:
            print(f"\nAttempting to send email to: {email_address}")
            send_email(email_address, metadata_file, pdf_path)

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(0)

    sys.exit(0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""System Info Report Tool"""

import platform
import os
import sys
import datetime
import socket
import logging
import argparse


def setup_logging(verbose, log_file):
    log_level = logging.DEBUG if verbose else logging.INFO
    log_format = '%(asctime)s - %(levelname)s - %(message)s'

    handlers = []
    if log_file:
        try:
            handlers.append(logging.FileHandler(log_file))
        except (IOError, OSError) as e:
            print(f"Warning: Could not create log file {log_file}: {e}", file=sys.stderr)

    if verbose:
        handlers.append(logging.StreamHandler(sys.stdout))

    if not handlers:
        handlers.append(logging.NullHandler())

    logging.basicConfig(
        level=log_level,
        format=log_format,
        handlers=handlers
    )


def get_system_info():
    logging.debug("Collecting system information")
    info = {}

    try:
        info["os"] = platform.system()
    except Exception as e:
        logging.warning(f"Failed to get OS: {e}")
        info["os"] = "Unknown"

    try:
        info["version"] = platform.version()
    except Exception as e:
        logging.warning(f"Failed to get version: {e}")
        info["version"] = "Unknown"

    try:
        info["system"] = platform.platform()
    except Exception as e:
        logging.warning(f"Failed to get system: {e}")
        info["system"] = "Unknown"

    try:
        info["release"] = platform.release()
    except Exception as e:
        logging.warning(f"Failed to get release: {e}")
        info["release"] = "Unknown"

    try:
        info["architecture"] = platform.machine()
    except Exception as e:
        logging.warning(f"Failed to get architecture: {e}")
        info["architecture"] = "Unknown"

    try:
        info["hostname"] = socket.gethostname()
    except Exception as e:
        logging.warning(f"Failed to get hostname: {e}")
        info["hostname"] = "Unknown"

    try:
        info["processor"] = platform.processor()
    except Exception as e:
        logging.warning(f"Failed to get processor: {e}")
        info["processor"] = "Unknown"

    try:
        info["python_version"] = sys.version.split()[0]
    except Exception as e:
        logging.warning(f"Failed to get Python version: {e}")
        info["python_version"] = "Unknown"

    try:
        info["node"] = platform.node()
    except Exception as e:
        logging.warning(f"Failed to get node: {e}")
        info["node"] = "Unknown"

    logging.debug(f"Collected {len(info)} system information fields")
    return info


def write_system_info(filename, info):
    logging.debug(f"Writing system information to {filename}")
    try:
        with open(filename, 'w') as f:
            f.write(f"System Information Report\n")
            f.write(f"Generated: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
            f.write(f"{'-' * 60}\n\n")

            for key, value in info.items():
                f.write(f"{key}: {value}\n")

        logging.info(f"Successfully wrote system information to {filename}")
        return True
    except (IOError, OSError, PermissionError) as e:
        logging.error(f"Failed to write to {filename}: {e}")
        return False
    except Exception as e:
        logging.error(f"Unexpected error writing to {filename}: {e}")
        return False


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="System Info Report Tool - Collect and report system information",
        formatter_class=argparse.RawDescriptionHelpFormatter
    )

    parser.add_argument(
        '-o', '--output',
        default='system_info.txt',
        help='Output file name (default: system_info.txt)'
    )

    parser.add_argument(
        '-v', '--verbose',
        action='store_true',
        help='Enable verbose output'
    )

    parser.add_argument(
        '-l', '--log-file',
        default=None,
        help='Log file path (optional)'
    )

    parser.add_argument(
        '--version',
        action='version',
        version='System Info Report Tool 1.0.0'
    )

    return parser.parse_args()


def main():
    args = parse_arguments()

    setup_logging(args.verbose, args.log_file)

    logging.info("System Info Report Tool initialized")

    try:
        system_info = get_system_info()

        if not system_info:
            logging.error("No system information collected")
            return 1

        success = write_system_info(args.output, system_info)

        if success:
            if args.verbose:
                print(f"System information written to {args.output}")
            logging.info("Report generation complete")
            return 0
        else:
            logging.error("Failed to write system information report")
            return 1

    except KeyboardInterrupt:
        logging.warning("Operation interrupted by user")
        return 130
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        return 1


if __name__ == "__main__":
    sys.exit(main())

