#!/usr/bin/env python3
"""
usb_monitor.py

Monitors USB device connect/disconnect events using platform-native
mechanisms. Logs each event to usb_log.txt in the current working
directory, then prints a summary and exits after MAX_EVENTS events.

Log format (one line per event):
  usb: connected, drive: /dev/sda, device: Kingston USB
"""

import sys
import os
import time
import platform
import datetime

MAX_EVENTS = 5
POLL_INTERVAL = 0.5  # seconds
LOG_FILE = "usb_log.txt"


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _timestamp() -> str:
    return datetime.datetime.now().isoformat(timespec="seconds")


def _write_log(entries: list[dict]) -> None:
    """Append event dicts to LOG_FILE."""
    with open(LOG_FILE, "a", encoding="utf-8") as fh:
        for e in entries:
            line = (
                f"timestamp: {e['timestamp']}, "
                f"usb: {e['usb']}, "
                f"drive: {e['drive']}, "
                f"device: {e['device']}\n"
            )
            fh.write(line)


# ---------------------------------------------------------------------------
# Linux helpers
# ---------------------------------------------------------------------------

_SYS_USB = "/sys/bus/usb/devices"


def _linux_devices() -> dict[str, dict]:
    """
    Return a mapping of sysfs device name -> {vendor, product, devnode}.
    Reads idVendor, idProduct, and manufacturer/product strings where
    available; resolves the /dev node via the 'block' sub-tree.
    """
    result: dict[str, dict] = {}
    try:
        entries = os.listdir(_SYS_USB)
    except OSError:
        return result

    for name in entries:
        dev_path = os.path.join(_SYS_USB, name)
        info: dict = {"vendor": "", "product": "", "devnode": "unknown"}

        for attr, key in (("idVendor", "vendor"), ("idProduct", "product")):
            try:
                with open(os.path.join(dev_path, attr), encoding="utf-8") as f:
                    info[key] = f.read().strip()
            except OSError:
                pass

        for label_file in ("product", "manufacturer"):
            try:
                with open(os.path.join(dev_path, label_file), encoding="utf-8") as f:
                    text = f.read().strip()
                    if text:
                        info["label"] = text
                        break
            except OSError:
                pass
        else:
            info.setdefault("label", f"{info['vendor']}:{info['product']}" or name)

        # Try to find an associated block device (e.g. sda)
        block_base = os.path.join(dev_path)
        for root, dirs, _ in os.walk(block_base):
            if "block" in dirs:
                block_dir = os.path.join(root, "block")
                try:
                    nodes = os.listdir(block_dir)
                    if nodes:
                        info["devnode"] = f"/dev/{nodes[0]}"
                except OSError:
                    pass
                break

        result[name] = info
    return result


def monitor_linux(max_events: int) -> int:
    previous = _linux_devices()
    events: list[dict] = []

    print(f"Monitoring USB events on Linux (polling {POLL_INTERVAL}s)...")
