    import subprocess

    devices: dict[str, dict] = {}

    try:
        result = subprocess.run(
            ["ioreg", "-p", "IOUSB", "-l", "-w0"],
            capture_output=True, text=True, timeout=5,
        )
    except (OSError, subprocess.TimeoutExpired):
        return devices

    location = label = None
    for line in result.stdout.splitlines():
        s = line.strip()
        if "+-o" in s:
            if location:
                devices[location] = {
                    "label": label or location,
                    "devnode": "unknown",
                }
            location = s.split("+-o", 1)[-1].strip().split("@")[0].strip() or None
            label = None
        elif '"locationID"' in s:
            try:
                location = s.split("=", 1)[1].strip()
            except IndexError:
                pass
        elif '"USB Product Name"' in s or '"kUSBProductString"' in s:
            try:
                label = s.split("=", 1)[1].strip().strip('"')
            except IndexError:
                pass

    if location:
        devices[location] = {"label": label or location, "devnode": "unknown"}

    # Attempt to map /dev/disk nodes via diskutil
    try:
        du = subprocess.run(
            ["diskutil", "list", "-plist"],
            capture_output=True, text=True, timeout=5,
        )
        # Simple parse: pull out /dev/disk entries
        for line in du.stdout.splitlines():
            line = line.strip()
            if line.startswith("/dev/disk"):
                dev = line.split()[0]
                # Associate with the last unmatched device as a best-effort
                for loc in devices:
                    if devices[loc]["devnode"] == "unknown":
                        devices[loc]["devnode"] = dev
                        break
    except (OSError, subprocess.TimeoutExpired):
        pass

    return devices


