#!/usr/bin/env python3
import sys
import os
from datetime import datetime


def parse_args():
    args = {
        'filepath': 'output.txt',
        'data': 'default_data',
        'verbose': False,
        'dry_run': False,
        'summary_only': False,
        'log_level': 'INFO'
    }

    positional = []
    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == '--verbose':
            args['verbose'] = True
        elif arg == '--dry-run':
            args['dry_run'] = True
        elif arg == '--summary-only':
            args['summary_only'] = True
        elif arg == '--log-level':
            if i + 1 < len(sys.argv):
                args['log_level'] = sys.argv[i + 1].upper()
                i += 1
            else:
                print("Error: --log-level requires a value", file=sys.stderr)
                sys.exit(1)
        elif not arg.startswith('--'):
            positional.append(arg)
        i += 1

    if len(positional) >= 1:
        args['filepath'] = positional[0]
    if len(positional) >= 2:
        args['data'] = positional[1]

    return args


def log_message(level, message, config):
    valid_levels = ['INFO', 'ERROR']
    if level not in valid_levels:
        level = 'INFO'

    if config['log_level'] == 'ERROR' and level == 'INFO':
        return

    if not config['summary_only']:
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        print(f"[{timestamp}] [{level}] {message}")


def validate_filepath(filepath, for_write=True):
    if for_write:
        parent_dir = os.path.dirname(filepath)
        if parent_dir and not os.path.exists(parent_dir):
            return False, f"Parent directory does not exist: {parent_dir}"

        if os.path.exists(filepath):
            if not os.path.isfile(filepath):
                return False, f"Path exists but is not a file: {filepath}"
            if not os.access(filepath, os.W_OK):
                return False, f"No write permission for file: {filepath}"
        else:
            parent_dir = parent_dir or '.'
            if not os.access(parent_dir, os.W_OK):
                return False, f"No write permission in directory: {parent_dir}"

    return True, None


def append_to_file(filepath, data, config):
    if config['dry_run']:
        log_message('INFO', f"DRY RUN: Would append {len(data)} bytes to {filepath}", config)
        return True

    try:
        with open(filepath, 'a') as f:
            f.write(data)
        log_message('INFO', f"Successfully appended data to {filepath}", config)
        return True
    except PermissionError:
        log_message('ERROR', f"Permission denied writing to {filepath}", config)
        return False
    except OSError as e:
        log_message('ERROR', f"OS error writing to {filepath}: {e}", config)
        return False
    except Exception as e:
        log_message('ERROR', f"Unexpected error writing to {filepath}: {e}", config)
        return False


def write_log_entry(filepath, data, data_size, config):
    log_path = 'append_log.txt'

    if config['dry_run']:
        log_message('INFO', f"DRY RUN: Would write log entry to {log_path}", config)
        return True

    try:
        log_entry = f'"{data}",{data_size},"{filepath}"\n'
        with open(log_path, 'a') as log_file:
            log_file.write(log_entry)
        log_message('INFO', f"Log entry written to {log_path}", config)
        return True
    except PermissionError:
        log_message('ERROR', f"Permission denied writing to {log_path}", config)
        return False
    except OSError as e:
        log_message('ERROR', f"OS error writing to {log_path}: {e}", config)
        return False
    except Exception as e:
        log_message('ERROR', f"Unexpected error writing to {log_path}: {e}", config)
        return False


def main():
    config = parse_args()

    valid, error = validate_filepath(config['filepath'], for_write=True)
    if not valid:
        log_message('ERROR', error, config)
        sys.exit(1)

    valid, error = validate_filepath('append_log.txt', for_write=True)
    if not valid:
        log_message('ERROR', error, config)
        sys.exit(1)

    data = config['data']
    data_size = len(data.encode('utf-8'))

    if config['verbose'] and not config['summary_only']:
        log_message('INFO', f"Starting append operation for {config['filepath']}", config)
        log_message('INFO', f"Data size: {data_size} bytes", config)
        if config['dry_run']:
            log_message('INFO', "Running in dry-run mode (no changes will be made)", config)

    success = append_to_file(config['filepath'], data, config)
    if not success:
        print("Summary: Operation failed, 0 bytes appended, 0 log entries written")
        sys.exit(1)

    log_success = write_log_entry(config['filepath'], data, data_size, config)
    if not log_success:
        print(f"Summary: {data_size} bytes appended, 0 log entries written (logging failed)")
        sys.exit(1)

    log_entries = 1 if not config['dry_run'] else 0
    bytes_appended = data_size if not config['dry_run'] else 0

    if config['dry_run']:
        print(f"Summary: DRY RUN - Would append {data_size} bytes, would write 1 log entry")
    else:
        print(f"Summary: {bytes_appended} bytes appended, {log_entries} log entry written")


if __name__ == "__main__":
    main()

