#!/usr/bin/env python3
"""
enumerate_software.py — Enumerate installed software across supported platforms.

Uses only the Python standard library. Detects the host operating system and
runs the appropriate package manager / registry commands to list installed
software, then prints a unified report to stdout.
"""

import json
import platform
import shutil
import subprocess
import sys
from dataclasses import dataclass
from typing import List, Optional


@dataclass
class SoftwareEntry:
    name: str
    version: str = ""
    source: str = ""


def _run_command(cmd: List[str], timeout: int = 30) -> Optional[str]:
    """Run a command safely and return stdout, or None on failure."""
    try:
        result = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
            check=False,
            text=True,
        )
        return result.stdout if result.returncode == 0 else None
    except (FileNotFoundError, subprocess.TimeoutExpired, PermissionError, OSError):
        return None


def _command_exists(cmd: str) -> bool:
    return shutil.which(cmd) is not None


# ---------------------------------------------------------------------------
# Platform-specific collectors
# ---------------------------------------------------------------------------

def _collect_dpkg() -> List[SoftwareEntry]:
    """Collect from dpkg (Debian/Ubuntu)."""
    output = _run_command(["dpkg-query", "-W", "-f=${Package}\t${Version}\n"])
    if not output:
        return []
    entries = []
    for line in output.strip().splitlines():
        parts = line.split("\t", 1)
        name = parts[0].strip()
        version = parts[1].strip() if len(parts) > 1 else ""
        if name:
            entries.append(SoftwareEntry(name, version, "dpkg"))
    return entries


def _collect_rpm() -> List[SoftwareEntry]:
    """Collect from rpm (Fedora/RHEL/CentOS/SUSE)."""
    output = _run_command(["rpm", "-qa", "--qf", "%{NAME}\t%{VERSION}-%{RELEASE}\n"])
    if not output:
        return []
    entries = []
    for line in output.strip().splitlines():
        parts = line.split("\t", 1)
        name = parts[0].strip()
        version = parts[1].strip() if len(parts) > 1 else ""
        if name:
            entries.append(SoftwareEntry(name, version, "rpm"))
    return entries


def _collect_pacman() -> List[SoftwareEntry]:
    """Collect from pacman (Arch Linux)."""
    output = _run_command(["pacman", "-Q"])
    if not output:
        return []
    entries = []
    for line in output.strip().splitlines():
        parts = line.split(None, 1)
        name = parts[0].strip() if parts else ""
        version = parts[1].strip() if len(parts) > 1 else ""
        if name:
            entries.append(SoftwareEntry(name, version, "pacman"))
    return entries


def _collect_snap() -> List[SoftwareEntry]:
    """Collect from snap packages."""
    if not _command_exists("snap"):
        return []
    output = _run_command(["snap", "list"])
    if not output:
        return []
    entries = []
    for line in output.strip().splitlines()[1:]:  # skip header
        parts = line.split()
        if len(parts) >= 2:
            entries.append(SoftwareEntry(parts[0].strip(), parts[1].strip(), "snap"))
    return entries


def _collect_flatpak() -> List[SoftwareEntry]:
    """Collect from flatpak packages."""
    if not _command_exists("flatpak"):
        return []
    output = _run_command(["flatpak", "list", "--columns=application,version"])
    if not output:
        return []
    entries = []
    for line in output.strip().splitlines():
        parts = line.split("\t", 1)
        name = parts[0].strip()
        version = parts[1].strip() if len(parts) > 1 else ""
        if name:
            entries.append(SoftwareEntry(name, version, "flatpak"))
    return entries


def _collect_homebrew() -> List[SoftwareEntry]:
    """Collect from Homebrew (macOS/Linux)."""
    if not _command_exists("brew"):
        return []
    output = _run_command(["brew", "list", "--versions"])
    if not output:
        return []
    entries = []
    for line in output.strip().splitlines():
        parts = line.split()
        if parts:
            name = parts[0].strip()
            version = parts[1].strip() if len(parts) > 1 else ""
            entries.append(SoftwareEntry(name, version, "homebrew"))
    return entries


def _collect_macos_pkgutil() -> List[SoftwareEntry]:
    """Collect from pkgutil receipts (macOS)."""
    output = _run_command(["pkgutil", "--pkgs"])
    if not output:
        return []
    entries = []
    for line in output.strip().splitlines():
        name = line.strip()
        if name:
            entries.append(SoftwareEntry(name, "", "pkgutil"))
    return entries


def _collect_macos_system_profiler() -> List[SoftwareEntry]:
    """Collect from system_profiler SPApplicationsDataType."""
    output = _run_command(
        ["system_profiler", "SPApplicationsDataType", "-detailLevel", "mini"],
        timeout=60,
    )
    if not output:
        return []
    entries = []
    for line in output.splitlines():
        stripped = line.strip()
        if ":" in stripped and not stripped.startswith("Location"):
            name = stripped.split(":", 1)[0].strip()
            if name and name != "Applications":
                entries.append(SoftwareEntry(name, "", "system_profiler"))
    return entries


def _collect_windows_wmic() -> List[SoftwareEntry]:
    """Collect from wmic product (Windows)."""
    output = _run_command(
        ["wmic", "product", "get", "Name,Version", "/format:csv"], timeout=60
    )
    if not output:
        return []
    entries = []
    for line in output.strip().splitlines()[1:]:  # skip header
        parts = line.strip().split(",")
        if len(parts) >= 3:
            name = parts[1].strip()
            version = parts[2].strip()
            if name:
                entries.append(SoftwareEntry(name, version, "wmic"))
    return entries


def _collect_windows_reg() -> List[SoftwareEntry]:
    """Collect from Windows registry via reg query (64-bit and 32-bit views)."""
    reg_paths = [
        r"HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall",
        r"HKLM\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall",
        r"HKCU\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall",
    ]
    entries = []
    for reg_path in reg_paths:
        output = _run_command(
            ["reg", "query", reg_path, "/s", "/v", "DisplayName"], timeout=60
        )
        if not output:
            continue
        for line in output.splitlines():
            stripped = line.strip()
            if stripped.startswith("DisplayName"):
                parts = stripped.split("REG_SZ", 1)
                if len(parts) > 1:
                    name = parts[1].strip()
                    if name:
                        entries.append(SoftwareEntry(name, "", "registry"))
    return entries


def _collect_windows_winget() -> List[SoftwareEntry]:
    """Collect from winget export."""
    if not _command_exists("winget"):
        return []
    output = _run_command(["winget", "export", "--output", "-", "--format", "json"])
    if not output:
        return []
    try:
        data = json.loads(output)
    except json.JSONDecodeError:
        return []
    entries = []
    for source in data.get("Sources", []):
        for pkg in source.get("Packages", []):
            entries.append(
                SoftwareEntry(
                    pkg.get("PackageIdentifier", ""),
                    pkg.get("Version", ""),
                    "winget",
                )
            )
    return entries


