def collect_linux() -> List[SoftwareEntry]:
    collectors = [
        _collect_dpkg,
        _collect_rpm,
        _collect_pacman,
        _collect_snap,
        _collect_flatpak,
    ]
    entries = []
    for collector in collectors:
        try:
            entries.extend(collector())
        except Exception:
            continue
    return entries


def collect_macos() -> List[SoftwareEntry]:
    collectors = [
        _collect_homebrew,
        _collect_macos_pkgutil,
        _collect_macos_system_profiler,
    ]
    entries = []
    for collector in collectors:
        try:
            entries.extend(collector())
        except Exception:
            continue
    return entries


def collect_windows() -> List[SoftwareEntry]:
    collectors = [
        _collect_windows_wmic,
        _collect_windows_reg,
        _collect_windows_winget,
    ]
    entries = []
    for collector in collectors:
        try:
            entries.extend(collector())
        except Exception:
            continue
    return entries


def collect() -> List[SoftwareEntry]:
    system = platform.system().lower()
    if system == "linux":
        return collect_linux()
    elif system == "darwin":
        return collect_macos()
    elif system == "windows":
        return collect_windows()
    return []


